//----------------[  button color manager  ]----------------
if (!function_exists('color_editor_payload')) {
    function color_editor_payload($mode, $textbotlang)
    {
        $setting = select("setting", "*", null, null, "select");
        $layout = json_decode($setting['keyboardmain'], true);
        $rows = (is_array($layout) && isset($layout['keyboard']) && is_array($layout['keyboard'])) ? $layout['keyboard'] : [];
        $labels = [
            'text_usertest' => $textbotlang['textbot']['userTest'],
            'text_Purchased_services' => $textbotlang['textbot']['purchasedServices'],
            'text_support' => $textbotlang['textbot']['support'],
            'text_help' => $textbotlang['textbot']['help'],
            'accountwallet' => $textbotlang['textbot']['accountWallet'],
            'addbalance' => $textbotlang['textbot']['addBalance'],
            'text_sell' => $textbotlang['textbot']['sell'],
            'text_Tariff_list' => $textbotlang['textbot']['tariffList'],
            'text_affiliates' => $textbotlang['textbot']['affiliates'],
            'text_wheel_luck' => $textbotlang['textbot']['wheelLuck'],
            'text_extend' => $textbotlang['textbot']['extend'],
            'text_change_language' => $textbotlang['language']['changeButton']
        ];
        $styleEmoji = ['' => '⚪', 'primary' => '🔵', 'success' => '🟢', 'danger' => '🔴'];
        $field = ($mode == 'r') ? 'style_reply' : 'style';
        $kb = ['inline_keyboard' => []];
        foreach ($rows as $r => $row) {
            if (!is_array($row)) {
                continue;
            }
            $kbRow = [];
            foreach ($row as $c => $btn) {
                if (!is_array($btn) || !isset($btn['text'])) {
                    continue;
                }
                $name = $btn['text'];
                if (isset($labels[$name])) {
                    $name = $labels[$name];
                }
                $style = (isset($btn[$field]) && in_array($btn[$field], ['primary', 'success', 'danger'], true)) ? $btn[$field] : '';
                $kbBtn = [
                    'text' => (!empty($btn['hidden']) ? '🚫 ' : '') . $name . ' ' . $styleEmoji[$style],
                    'callback_data' => "btncolor-{$mode}-{$r}-{$c}"
                ];
                if ($style !== '') {
                    $kbBtn['style'] = $style;
                }
                $kbRow[] = $kbBtn;
            }
            if (!empty($kbRow)) {
                $kb['inline_keyboard'][] = $kbRow;
            }
        }
        $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبلی', 'callback_data' => 'btnset_open:color', 'style' => 'danger']];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
        return json_encode($kb);
    }
}

if (!function_exists('lang_scope_display')) {
    function lang_scope_display($lang, $textbotlang)
    {
        if ($lang === '' || $lang === null || $lang === 'all') {
            return $textbotlang['Admin']['LangScope']['allLangsBtn'];
        }
        // the column has always been allowed to hold a comma list ("fa,en") for
        // multi-language visibility (every read site uses FIND_IN_SET), but this
        // helper used to only label a single code and printed the raw string for
        // anything else - render each part with its own flag label instead
        $parts = array_filter(array_map('trim', explode(',', (string) $lang)), 'strlen');
        if (count($parts) <= 1) {
            return $textbotlang['bottext']['langs'][$lang] ?? $lang;
        }
        $labels = [];
        foreach ($parts as $code) {
            $labels[] = $textbotlang['bottext']['langs'][$code] ?? $code;
        }
        return implode(' ', $labels);
    }
}
if (!function_exists('langscope_kind_meta')) {
    // maps a langscope "kind" to its table/id-column/name-column, and the
    // right list caption key - the one place that knows about all three
    // entity types, so every other langscope_* function stays generic
    function langscope_kind_meta($kind)
    {
        if ($kind === 'panel') {
            return ['table' => 'marzban_panel', 'idField' => 'code_panel', 'nameField' => 'name_panel', 'captionKey' => 'panelsListCaption'];
        }
        if ($kind === 'product') {
            return ['table' => 'product', 'idField' => 'id', 'nameField' => 'name_product', 'captionKey' => 'productsListCaption'];
        }
        return ['table' => 'category', 'idField' => 'id', 'nameField' => 'remark', 'captionKey' => 'categoriesListCaption'];
    }
}
