if (!function_exists('langscope_list_payload')) {
    // one list per kind (panel/product/category): every row + its current
    // language, tap to open the picker for that one item
    function langscope_list_payload($kind, $textbotlang)
    {
        $meta = langscope_kind_meta($kind);
        $rows = select($meta['table'], "*", null, null, "fetchAll");
        $kb = ['inline_keyboard' => []];
        if (!is_array($rows) || empty($rows)) {
            $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['emptyList'], 'callback_data' => 'langscope_hub']];
        } else {
            foreach ($rows as $row) {
                $label = $row[$meta['nameField']] . ' — ' . lang_scope_display($row['lang'] ?? 'all', $textbotlang);
                $kb['inline_keyboard'][] = [['text' => $label, 'callback_data' => "langscope_open:{$kind}:{$row[$meta['idField']]}"]];
            }
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['backToHubBtn'], 'callback_data' => 'langscope_hub']];
        return json_encode($kb);
    }
}
if (!function_exists('lang_scope_picker_payload')) {
    // single-tap picker: 5 languages + "all languages", used identically for
    // panels, products and categories via the unified langscope_set:{kind}
    // callback - the underlying table/column differences are resolved once,
    // in langscope_kind_meta()
    // multi-select: one or many languages per panel/product/category. Each
    // language button carries the bitmask it would produce if tapped, so the
    // in-progress selection lives entirely in callback_data - no server-side
    // session state, exactly like the cascade picker below. $bitmask is null on
    // first open (derived from what is stored) and supplied on every re-render.
    function lang_scope_picker_payload($kind, $id, $currentLang, $textbotlang, $bitmask = null)
    {
        $langs = ['fa', 'en', 'ru', 'zh', 'tk'];
        if ($bitmask === null) {
            $bitmask = langscope_casc_lang_to_bitmask($currentLang);
        }
        $kb = ['inline_keyboard' => []];
        $row = [];
        foreach ($langs as $i => $code) {
            $bits = $bitmask;
            $bits[$i] = ($bits[$i] === '1') ? '0' : '1';
            $mark = ($bitmask[$i] === '1') ? '✅ ' : '';
            $row[] = ['text' => $mark . $textbotlang['bottext']['langs'][$code], 'callback_data' => "langscope_tog:{$kind}:{$id}:{$bits}"];
            if (count($row) === 2) {
                $kb['inline_keyboard'][] = $row;
                $row = [];
            }
        }
        if (!empty($row)) {
            $kb['inline_keyboard'][] = $row;
        }
        $isAll = (strpos($bitmask, '1') === false);
        $kb['inline_keyboard'][] = [['text' => ($isAll ? '✅ ' : '') . $textbotlang['Admin']['LangScope']['allLangsBtn'], 'callback_data' => "langscope_set:{$kind}:{$id}:all"]];
        if (!$isAll) {
            $kb['inline_keyboard'][] = [['text' => '💾 ذخیره', 'callback_data' => "langscope_apply:{$kind}:{$id}:{$bitmask}", 'style' => 'success']];
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['backToHubBtn'], 'callback_data' => "langscope_list:{$kind}"]];
        return json_encode($kb);
    }
}
if (!function_exists('langscope_casc_lang_to_bitmask')) {
    // converts a stored lang value ('all', '', null, or a comma list like
    // "fa,en") into a 5-char 1/0 string over [fa,en,ru,zh,tk], used as the
    // multi-select picker's transient state (carried in callback_data, no
    // server-side session needed)
    function langscope_casc_lang_to_bitmask($langValue)
    {
        $langs = ['fa', 'en', 'ru', 'zh', 'tk'];
        if ($langValue === 'all' || $langValue === null || $langValue === '') {
            return '00000';
        }
        $parts = array_map('trim', explode(',', $langValue));
        $bits = '';
        foreach ($langs as $code) {
            $bits .= in_array($code, $parts, true) ? '1' : '0';
        }
        return $bits;
    }
}
if (!function_exists('langscope_casc_bitmask_to_langs')) {
    function langscope_casc_bitmask_to_langs($bitmask)
    {
        $langs = ['fa', 'en', 'ru', 'zh', 'tk'];
        $picked = [];
        for ($i = 0; $i < 5; $i++) {
            if (($bitmask[$i] ?? '0') === '1') {
                $picked[] = $langs[$i];
            }
        }
        return $picked;
    }
}
if (!function_exists('langscope_cascade_hub_payload')) {
    function langscope_cascade_hub_payload($textbotlang)
    {
        $cats = select("category", "*", null, null, "fetchAll");
        $kb = ['inline_keyboard' => []];
        if (!is_array($cats) || empty($cats)) {
            $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['emptyList'], 'callback_data' => 'langscope_hub']];
        } else {
            foreach ($cats as $c) {
                $kb['inline_keyboard'][] = [['text' => $c['remark'], 'callback_data' => "langscope_casc_pick:{$c['id']}"]];
            }
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['backToHubBtn'], 'callback_data' => 'langscope_hub']];
        return json_encode($kb);
    }
}
if (!function_exists('langscope_casc_picker_payload')) {
    // multi-select language picker: each button already carries the target
    // bitmask it would produce if tapped, so toggling never needs anything
    // beyond re-rendering with that new callback_data's bitmask
    function langscope_casc_picker_payload($catId, $bitmask, $textbotlang)
    {
        $langs = ['fa', 'en', 'ru', 'zh', 'tk'];
        $kb = ['inline_keyboard' => []];
        $row = [];
        foreach ($langs as $i => $code) {
            $bits = $bitmask;
            $bits[$i] = ($bits[$i] === '1') ? '0' : '1';
            $mark = ($bitmask[$i] === '1') ? '✅ ' : '';
            $row[] = ['text' => $mark . $textbotlang['bottext']['langs'][$code], 'callback_data' => "langscope_casc_toggle:{$catId}:{$bits}"];
            if (count($row) === 2) {
                $kb['inline_keyboard'][] = $row;
                $row = [];
            }
        }
        if (!empty($row)) {
            $kb['inline_keyboard'][] = $row;
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['cascadeApplyBtn'], 'callback_data' => "langscope_casc_apply:{$catId}:{$bitmask}", 'style' => 'success']];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['backToHubBtn'], 'callback_data' => 'langscope_casc_hub']];
        return json_encode($kb);
    }
}
