        // bottext home list already does for its group-launcher rows
        $bt_is_customized = function ($key) use ($bt_lang, $bt_te, $bt_st, $bt_re, $bt_be) {
            $textCustom = is_array($bt_te) && isset($bt_te[$bt_lang]) && bottext_dotted_isset($bt_te[$bt_lang], $key);
            $stickerCustom = bt_media_lookup($bt_st, $key, $bt_lang) !== '';
            $reactCustom = bt_media_lookup($bt_re, $key, $bt_lang) !== '';
            $btnCustom = is_array($bt_be) && !empty($bt_be[$bt_lang][$key]);
            return $textCustom || $stickerCustom || $reactCustom || $btnCustom;
        };
        // reaction needs a triggering user message — only these keys have one
        $bt_can_react = in_array($bt_key, ['users.text_start', 'textbot.faqDesc', 'textbot.tariffListDesc', 'textbot.rules', 'users.unknownMsg'], true);
        // Items whose text is not a message of its own: it is concatenated into
        // ANOTHER caption, or shown as an Alert popup. There is no message to
        // attach a sticker or a reaction to, and a "👁 پیش‌نمایش" screen showing
        // a fragment out of the caption it belongs to told the admin less than
        // simply quoting the current text right here does - the same way the
        // gateway caption screens (💳 کپشن و دکمه‌های درگاه‌ها) already work.
        $bt_inline = in_array($bt_key, bt_inline_block_keys(), true);
        // A sticker only ever fires from sendmessage()/Editmessagetext() (see
        // bottext_send_extras() in botapi.php). These texts go out as a photo
        // or a document caption instead, which never reaches that path - so the
        // setting sat there doing nothing.
        $bt_nosticker = $bt_inline || in_array($bt_key, bt_media_message_keys(), true);
        // blocks and temporary texts whose sticker could never be useful
        if (function_exists('bt_nosticker_keys') && in_array($bt_key, bt_nosticker_keys(), true)) {
            $bt_nosticker = true;
        }
        // NOTE: users.status.getConfigHintBuy deliberately does NOT go in this
        // list - like its usertest counterpart users.status.getConfigHint, its
        // "buttons" aren't genbtn-shaped (button_edit[lang][key]) but the
        // separate configDisplayBuy/configColOrderBuy pair, so it gets its own
        // forward link straight from the myservices list (keyboard.php) instead
        // of the generic $bt_btn_label/$bt_btn_custom status line below.
        $bt_has_buttons = in_array($bt_key, ['users.usertest.selectUsernamePrompt', 'users.Balance.insufficientBalanceSimple', 'users.sell.selectUsernamePrompt', 'users.sell.preInvoice', 'users.sell.preInvoice2', 'textbot.preInvoice', 'users.sell.service_not_available', 'textbot.testExpired', 'users.sell.service_sell', 'users.status.infoFull', 'users.Balance.chargeSuccess', 'textbot.channel', 'users.extend.invoiceCreated', 'users.changeLink.warnchange', 'textbot.afterPay', 'textbot.afterText'], true);
        $info = "📝 <b>{$bt_label}</b>\n➖➖➖➖➖➖➖➖➖➖\n{$bt_extra_note}";
        $info .= "✏️ متن: " . ($bt_custom ? "سفارشی ✅" : "پیش‌فرض") . "\n";
        if (!$bt_nosticker) {
            $info .= "🖼 استیکر: " . ($bt_sticker !== '' ? "ست شده ✅" : "ندارد ❌") . "\n";
        }
        if ($bt_can_react && !$bt_nosticker) {
            $info .= "❤️ ری‌اکشن: " . ($bt_react !== '' ? $bt_react : "ندارد ❌") . "\n";
        }
        $bt_btn_custom = false;
        if ($bt_has_buttons) {
            $bt_btn_label = '🔘 دکمه‌های انصراف/پیش‌فرض';
            if ($bt_key === 'users.Balance.insufficientBalanceSimple') {
                $bt_btn_label = '🔘 دکمه افزایش موجودی';
            } elseif (in_array($bt_key, ['users.sell.preInvoice', 'users.sell.preInvoice2', 'textbot.preInvoice'], true)) {
                $bt_btn_label = '🔘 دکمه‌های تأیید خرید';
            } elseif ($bt_key === 'users.sell.service_not_available') {
                $bt_btn_label = '🔘 دکمه تهیه اشتراک';
            } elseif ($bt_key === 'textbot.testExpired') {
                $bt_btn_label = '🔘 دکمه خرید سرویس';
            } elseif ($bt_key === 'users.sell.service_sell') {
                $bt_btn_label = '🔘 دکمه بستن';
            } elseif ($bt_key === 'users.status.infoFull') {
                $bt_btn_label = '🔘 دکمه‌های صفحه‌ی وضعیت (تا ۱۳ تا)';
            } elseif ($bt_key === 'users.Balance.chargeSuccess') {
                $bt_btn_label = '🔘 دکمه تهیه اشتراک';
            } elseif ($bt_key === 'textbot.channel') {
                $bt_btn_label = '📯 دکمه‌های کانال';
            } elseif ($bt_key === 'users.extend.invoiceCreated') {
                $bt_btn_label = '🔘 دکمه‌های تأیید تمدید/بازگشت';
            } elseif ($bt_key === 'users.changeLink.warnchange') {
                $bt_btn_label = '🔘 دکمه‌های تایید/بازگشت';
            } elseif (in_array($bt_key, ['textbot.afterPay', 'textbot.afterText'], true)) {
                $bt_btn_label = '📚 دکمه مشاهده آموزش';
            }
            // 'cf' is shared across three caption screens - checked here so its
            // own status line is accurate no matter which of the three is open
            if (in_array($bt_key, ['users.sell.preInvoice', 'users.sell.preInvoice2', 'textbot.preInvoice'], true)) {
                $bt_be_key = 'users.sell.confirmButtons';
            } else {
                $bt_be_key = $bt_key;
            }
            // textbot.channel's buttons live on the channels table + its own
            // order setting, not in the shared button_edit blob every other
            // item uses - so its customized-state check is computed there too.
            if ($bt_key === 'textbot.channel') {
                $bt_btn_custom = channel_buttons_any_customized();
            } else {
                $bt_btn_custom = is_array($bt_be) && !empty($bt_be[$bt_lang][$bt_be_key]);
            }
            $info .= "{$bt_btn_label}: " . ($bt_btn_custom ? "سفارشی ✅" : "پیش‌فرض") . "\n";
        }
        // The live text, quoted right here - on every item, the way the gateway
        // caption screens (💳 کپشن و دکمه‌های درگاه‌ها) already work. Read through
        // the same resolver the customer-facing code uses, so a reset shows the
        // default immediately instead of a stale copy. This replaces the
        // 👁 پیش‌نمایش button, which existed only to show exactly this.
        // $bt_lang, not the global: this screen is showing ONE language's text,
        // and the global is always the reading admin's own account language.
        // Every caller of this function - 🎨 شخصی‌سازی, the cfgdeliv| delivery
        // screens, the reset confirmation - already passes the tab it is on, so
        // fixing it here fixes all of them without touching one call site.
        $info .= "➖➖➖➖➖➖➖➖➖➖\n👁 <b>متن فعلی:</b>\n" . bt_current_text_quote($bt_key, 1200, $bt_lang) . "\n";
        if ($bt_key === 'users.usertest.selectUsernamePrompt') {
            // this one prompt is followed immediately by a second message the
