        } elseif ($bt_key === 'users.status.infoFull') {
            $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبل', 'callback_data' => "bt_group|{$bt_lang}|myservices", 'style' => 'danger']];
        } elseif (in_array($bt_key, ['bottext.langPickerCaption', 'bottext.langBlockedMsg'], true)) {
            // both belong to the language screen and are only reachable from it
            $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبل', 'callback_data' => 'bt_langswitch', 'style' => 'danger']];
        } elseif ($bt_key === 'users.Balance.chargeSuccessDiscount') {
            $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبل', 'callback_data' => "bt_edit|{$bt_lang}|users.Balance.chargeSuccess", 'style' => 'danger']];
        } elseif ($bt_key === 'textbot.afterText' || $bt_key === 'users.usertest.noPanel' || $bt_key === 'textbot.selectLocationTest') {
            $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبل', 'callback_data' => "bt_edit|{$bt_lang}|users.usertest.selectUsernamePrompt", 'style' => 'danger']];
        } elseif ($bt_key === 'textbot.testExpired') {
            // bottext.btnCloseTest used to need the same case here, but it now
            // short-circuits to genbtn_detail_payload() at the top of this
            // function, which computes its own back target (bt_btnitem_back_cb())
            $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبل', 'callback_data' => "bt_edit|{$bt_lang}|users.usertest.selectUsernamePrompt", 'style' => 'danger']];
        }
        $kb['inline_keyboard'][] = [['text' => '🔙 برگشت به لیست', 'callback_data' => "btact|back|{$bt_lang}", 'style' => 'danger']];
        $kb['inline_keyboard'][] = [['text' => '❌ بستن', 'callback_data' => 'bt_close', 'style' => 'danger']];
        return [$info, json_encode($kb)];
    }
}

if (!function_exists('bt_current_text_quote')) {
    // One item's live text, quoted, for the top of its editing screen.
    //
    // Capped: this now sits on the screen itself rather than behind a button,
    // and an admin's own 3000-character welcome text would push the whole
    // message past Telegram's 4096 limit - which would not truncate the
    // preview, it would fail the edit and leave the admin staring at the
    // previous screen with no way to fix anything.
    // $lang is appended AFTER $limit and never before it: an existing caller
    // that passes $limit positionally as its second argument must keep working.
    function bt_current_text_quote($key, $limit = 1200, $lang = null)
    {
        $txt = bottext_resolve_key($key, $lang);
        if (trim((string) $txt) === '') {
            return topup_packages_caption_preview_quote('⚠️ متن پیدا نشد.');
        }
        if (mb_strlen($txt) > $limit) {
            // cut on the raw string, so a tag split in half cannot leak an
            // unclosed element into the screen's own markup
            $txt = strip_tags($txt);
            $txt = mb_substr($txt, 0, $limit) . '…';
        }
        return topup_packages_caption_preview_quote($txt);
    }
}
if (!function_exists('bt_inline_block_keys')) {
    // Registry items that are NOT a message of their own. Two kinds, one rule:
    // there is no Telegram message here to hang a sticker or a reaction on, so
    // those controls are hidden and the current text is quoted on the editing
    // screen itself instead of behind a 👁 پیش‌نمایش button that would show a
    // fragment stripped of the caption it lives in.
    //
    // Anything added here must genuinely be one of the two - a line/block
    // concatenated into another caption, or an answerCallbackQuery alert. A
    // real message that merely looks small still belongs outside this list.
    function bt_inline_block_keys()
    {
        return [
            // blocks concatenated into the payment-method caption
            'users.Balance.topupDiscActiveBlock',
            'users.Balance.topupDiscAutoBlock',
            // the quote appended to the top-up confirmation message
            'users.Balance.chargeSuccessDiscount',
            // the exact-amount warning appended to the card-to-card invoice:
            // the message the customer gets starts with the invoice caption, so
            // this text is never at the front and never matches
            'textbot.cardRandomAmountNotice',
            // single lines rendered inside a blockquote on the amount screens.
            // The two "All" variants belong with the other four - they were
            // simply missed when this list was written.
            'hardcoded.topupDiscPercentCaption',
            'hardcoded.topupDiscFixedCaption',
            'hardcoded.topupDiscGroupPercentCaption',
            'hardcoded.topupDiscGroupFixedCaption',
            'hardcoded.topupDiscAllPercentCaption',
            'hardcoded.topupDiscAllFixedCaption',
            // the same kind of line, inside the payment invoice
            'hardcoded.topupDiscPkgPercent',
            'hardcoded.topupDiscPkgFixed',
            // ...and their 💰 حداقل مبلغ variants
            'hardcoded.topupDiscMinPercentCaption',
            'hardcoded.topupDiscMinFixedCaption',
            'hardcoded.topupDiscMinPkgPercent',
            'hardcoded.topupDiscMinPkgFixed',
            'hardcoded.topupDiscMinSuffix',
            // a line inside the service-status caption
            'users.status.svcLocationMore',
            // button labels: there is no message to attach a sticker to, and
            // their own colour row takes the place of one
            'users.sell.backToPreviousBtn',
            'users.sell.backToPanelListBtn',
            'bottext.btnCloseBuy',
            'bottext.btnCloseTopup',
            'bottext.btnCloseAccount',
            'bottext.btnCloseTest',
            'bottext.btnCloseHelp',
            // alerts: answerCallbackQuery carries text and nothing else
            'users.status.svcUsageUnavailable',
            'users.extend.insufficientBalanceAlert',
            'keyboard.infoRefreshed',
        ];
    }
    // These ARE messages of their own, but they leave as a photo or a document
    // caption. bottext_send_extras() - the only thing that ever fires a text
    // sticker - hangs off sendmessage() and Editmessagetext() alone, so a
    // sticker set here could never appear. They keep their text editor and
    // their buttons; only the 🖼 استیکر row goes.
    function bt_media_message_keys()
    {
        return [
            // the service screen and the two subscription screens carry the
            // subscription QR (photo) or the WireGuard .conf (document)
            'users.status.infoFull',
            'users.status.linksubCaption',
            'users.status.subscriptionFile',
            // both config-delivery messages ride along with the config QR;
            // only a panel with no QR-able link falls back to plain text
            'textbot.afterPay',
            'textbot.afterText',
        ];
    }
}
if (!function_exists('emoji_sticker_editor_payload')) {
    function emoji_sticker_editor_payload($kind, $textbotlang)
    {
        $setting = select("setting", "*", null, null, "select");
        $layout = json_decode($setting['keyboardmain'], true);
        $rows = (is_array($layout) && isset($layout['keyboard']) && is_array($layout['keyboard'])) ? $layout['keyboard'] : [];
        $labels = menu_button_labels($textbotlang);
        $prefix = ($kind == 'emoji') ? 'btnemoji' : 'btnsticker';
        $es_simple_mode = (is_array($layout) && !empty($layout['simple_emoji']));
        $es_pos_global = (is_array($layout) && isset($layout['emoji_pos_global']) && $layout['emoji_pos_global'] === 'left') ? 'left' : 'right';
        $es_use_inline = (isset($setting['inlinebtnmain']) && $setting['inlinebtnmain'] == "oninline");
        $kb = ['inline_keyboard' => []];
        foreach ($rows as $r => $row) {
            if (!is_array($row)) {
                continue;
            }
            $kbRow = [];
            foreach ($row as $c => $btn) {
                if (!is_array($btn) || !isset($btn['text'])) {
                    continue;
                }
                if ($kind == 'emoji') {
                    // live preview: render exactly like the user's menu
                    $name = $btn['text'];
                    if (isset($labels[$name])) {
                        $name = $labels[$name];
                    }
                    if (isset($btn['custom_text']) && $btn['custom_text'] !== '') {
                        $name = $btn['custom_text'];
                    }
                    $kbBtn = [
                        'text' => $name,
                        'callback_data' => "{$prefix}-{$r}-{$c}"
                    ];
                    if (isset($btn['icon_emoji']) && $btn['icon_emoji'] !== '') {
                        $kbBtn['text'] = strip_leading_emoji($name);
                        $kbBtn['icon_custom_emoji_id'] = $btn['icon_emoji'];
                    } elseif (isset($btn['emoji']) && $btn['emoji'] !== '') {
                        if ($es_pos_global === 'left') {
                            $kbBtn['text'] = strip_leading_emoji($name) . ' ' . $btn['emoji'];
                        } else {
                            $kbBtn['text'] = $btn['emoji'] . ' ' . strip_leading_emoji($name);
                        }
                    } elseif ($es_simple_mode) {
                        $kbBtn['text'] = strip_leading_emoji($name);
                    } else {
                        // reposition the default text emoji per global setting (live preview)
                        list($es_def_emoji, $es_def_rest) = split_leading_emoji($name);
                        if ($es_def_emoji !== '') {
                            $kbBtn['text'] = ($es_pos_global === 'left') ? $es_def_rest . ' ' . $es_def_emoji : $es_def_emoji . ' ' . $es_def_rest;
                        }
                    }
                    if (!empty($btn['hidden'])) {
                        $kbBtn['text'] = '🚫 ' . $kbBtn['text'];
                    }
                } else {
                    $name = $btn['text'];
                    if (isset($labels[$name])) {
                        $name = $labels[$name];
                    }
                    $kbBtn = [
                        'text' => (!empty($btn['hidden']) ? '🚫 ' : '') . $name . ' ' . (!empty($btn['sticker']) ? '✅' : '❌'),
                        'callback_data' => "{$prefix}-{$r}-{$c}"
                    ];
                }
                $es_color = $es_use_inline ? (isset($btn['style']) ? $btn['style'] : '') : (isset($btn['style_reply']) ? $btn['style_reply'] : '');
                if ($es_color !== '' && in_array($es_color, ['primary', 'success', 'danger'], true)) {
                    $kbBtn['style'] = $es_color;
                }
                $kbRow[] = $kbBtn;
            }
            if (!empty($kbRow)) {
                $kb['inline_keyboard'][] = $kbRow;
            }
        }
        if ($kind == 'emoji') {
            $es_simple_on = (is_array($layout) && !empty($layout['simple_emoji']));
            $kb['inline_keyboard'][] = [['text' => ($es_simple_on ? '🔲 حالت ساده: ✅ روشن' : '🔲 حالت ساده: ❌ خاموش'), 'callback_data' => 'emojisimple']];
            $kb['inline_keyboard'][] = [
                ['text' => '⬅️ چپ' . ($es_pos_global === 'left' ? ' ✅' : ''), 'callback_data' => 'emojiposall-left'],
                ['text' => 'راست ➡️' . ($es_pos_global === 'right' ? ' ✅' : ''), 'callback_data' => 'emojiposall-right']
            ];
            $kb['inline_keyboard'][] = [['text' => '🔄 ریست همه ایموجی‌های کاستوم', 'callback_data' => 'emojiresetall', 'style' => 'danger']];
        } else {
            $kb['inline_keyboard'][] = [['text' => '🔄 ریست همه استیکرهای دکمه‌ها', 'callback_data' => 'stickerresetall', 'style' => 'danger']];
        }
        $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبلی', 'callback_data' => 'btnset_open:emoji', 'style' => 'danger']];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
        return json_encode($kb);
    }
}

if (!function_exists('layout_editor_payload')) {
    function layout_editor_payload($textbotlang, $selected = null)
    {
        $setting = select("setting", "*", null, null, "select");
        $layout = json_decode($setting['keyboardmain'], true);
        $rows = (is_array($layout) && isset($layout['keyboard']) && is_array($layout['keyboard'])) ? $layout['keyboard'] : [];
        $labels = menu_button_labels($textbotlang);
        $kb = ['inline_keyboard' => []];
        foreach ($rows as $r => $row) {
            if (!is_array($row)) {
                continue;
            }
            $kbRow = [];
            foreach ($row as $c => $btn) {
                if (!is_array($btn) || !isset($btn['text'])) {
                    continue;
                }
                $name = $btn['text'];
                if (isset($labels[$name])) {
                    $name = $labels[$name];
                }
                if (!empty($btn['hidden'])) {
                    $name = '🚫 ' . $name;
                }
                $isSel = ($selected !== null && $selected[0] == $r && $selected[1] == $c);
                if ($isSel) {
                    $name = '🔵 ' . $name;
                    $cb = "layoutcancel";
                } elseif ($selected !== null) {
                    $cb = "layoutswap-{$selected[0]}-{$selected[1]}-{$r}-{$c}";
                } else {
                    $cb = "layoutbtn-{$r}-{$c}";
                }
                $kbBtn = ['text' => $name, 'callback_data' => $cb];
                $ed_color = (isset($setting['inlinebtnmain']) && $setting['inlinebtnmain'] == "oninline") ? (isset($btn['style']) ? $btn['style'] : '') : (isset($btn['style_reply']) ? $btn['style_reply'] : '');
                if ($ed_color !== '' && in_array($ed_color, ['primary', 'success', 'danger'], true)) {
                    $kbBtn['style'] = $ed_color;
                }
                $kbRow[] = $kbBtn;
            }
            if (!empty($kbRow)) {
                $kb['inline_keyboard'][] = $kbRow;
            }
        }
        if ($selected !== null) {
            $kb['inline_keyboard'][] = [
                ['text' => '🔲 تمام‌عرض / کنار هم', 'callback_data' => "layoutfull-{$selected[0]}-{$selected[1]}"]
            ];
        }
        $kb['inline_keyboard'][] = [['text' => '🔄 ریست چیدمان به پیش‌فرض', 'callback_data' => "layoutreset"]];
        $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به منوی قبلی', 'callback_data' => 'bt_btnsettings', 'style' => 'danger']];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
        return json_encode($kb);
    }
}

if (!function_exists('lang_switch_settings_payload')) {
    // 🌐 تنظیمات تغییر زبان کاربر - everything about the language picker on one
    // screen, grouped under white dividers instead of one flat list: when it
    // shows, which languages it offers, how it looks, and who the bot serves.
    function lang_switch_settings_payload()
    {
        $ls = lang_switch_settings(true);
        $lsw_names = ['fa' => '🇮🇷 فارسی', 'en' => '🇬🇧 English', 'ru' => '🇷🇺 Русский', 'zh' => '🇨🇳 中文', 'tk' => '🇹🇲 Türkmençe'];
        $kb = ['inline_keyboard' => []];

        $kb['inline_keyboard'][] = [['text' => bt_section_meta('langsw_when')['label'], 'callback_data' => 'bt_sep|langsw_when']];
        $kb['inline_keyboard'][] = [[
            'text' => $ls['enabled'] ? '✅ نمایش خودکار منوی زبان: روشن' : '❌ نمایش خودکار منوی زبان: خاموش',
            'callback_data' => 'lsw_toggle',
            'style' => $ls['enabled'] ? 'success' : 'danger',
        ]];
        if ($ls['enabled']) {
            $kb['inline_keyboard'][] = [
                ['text' => ($ls['mode'] === 'once' ? '✅ ' : '') . '🆕 فقط بار اول', 'callback_data' => 'lsw_mode-once', 'style' => 'primary'],
                ['text' => ($ls['mode'] === 'always' ? '✅ ' : '') . '🔁 هر بار /start', 'callback_data' => 'lsw_mode-always', 'style' => 'primary'],
            ];
        }

        $kb['inline_keyboard'][] = [['text' => bt_section_meta('langsw_langs')['label'], 'callback_data' => 'bt_sep|langsw_langs']];
        foreach ($lsw_names as $lsw_code => $lsw_label) {
            $lsw_on = in_array($lsw_code, $ls['langs'], true);
            // ✅/❌ like every other toggle in the bot. The empty ⬜ read as an
            // unticked checkbox waiting to be filled rather than as "off".
            $kb['inline_keyboard'][] = [[
                'text' => ($lsw_on ? '✅ ' : '❌ ') . $lsw_label,
                'callback_data' => "lsw_lang-{$lsw_code}",
                'style' => $lsw_on ? 'success' : 'danger',
            ]];
        }

        $kb['inline_keyboard'][] = [['text' => bt_section_meta('langsw_look')['label'], 'callback_data' => 'bt_sep|langsw_look']];
        $kb['inline_keyboard'][] = [
            ['text' => '📋 کپشن پیش‌فرض', 'callback_data' => 'btact|rsttext|fa|bottext.langPickerCaption'],
            ['text' => '✏️ ویرایش کپشن', 'callback_data' => 'btact|text|fa|bottext.langPickerCaption', 'style' => 'primary'],
        ];
        // the same four tools every other button family has, on the picker's
        // own buttons - they were hardcoded two-per-row with no styling at all
        $kb['inline_keyboard'][] = [['text' => '🔘 ظاهر دکمه‌های انتخاب زبان', 'callback_data' => 'btnstyle_kindhub:langpick:fa', 'style' => 'primary']];

        $kb['inline_keyboard'][] = [['text' => bt_section_meta('langsw_access')['label'], 'callback_data' => 'bt_sep|langsw_access']];
        $kb['inline_keyboard'][] = [[
            'text' => ($ls['blockOthers'] ? '✅ ' : '❌ ') . '🚫 فقط زبان‌های انتخاب‌شده سرویس بگیرن',
            'callback_data' => 'lsw_blockothers',
            'style' => $ls['blockOthers'] ? 'success' : 'danger',
        ]];
        if ($ls['blockOthers']) {
            $kb['inline_keyboard'][] = [
                ['text' => '📋 پیش‌فرض', 'callback_data' => 'btact|rsttext|fa|bottext.langBlockedMsg'],
                ['text' => '✏️ ویرایش پیام رد', 'callback_data' => 'btact|text|fa|bottext.langBlockedMsg', 'style' => 'primary'],
            ];
        }

        $kb['inline_keyboard'][] = [['text' => '🔙 برگشت به لیست', 'callback_data' => 'btact|back|fa', 'style' => 'danger']];
        $kb['inline_keyboard'][] = [['text' => '❌ بستن', 'callback_data' => 'bt_close', 'style' => 'danger']];
        return json_encode($kb);
    }
    // what the screen says above those buttons, with a live preview of the
    // picker exactly as a user would receive it
    function lang_switch_settings_caption($textbotlang)
    {
        $ls = lang_switch_settings();
        $names = ['fa' => '🇮🇷 فارسی', 'en' => '🇬🇧 English', 'ru' => '🇷🇺 Русский', 'zh' => '🇨🇳 中文', 'tk' => '🇹🇲 Türkmençe'];
        $on = [];
        foreach ($ls['langs'] as $c) {
            $on[] = $names[$c] ?? $c;
        }
        $cap = "🌐 <b>تنظیمات تغییر زبان کاربر</b>\n➖➖➖➖➖➖➖➖➖➖\n";
        $cap .= "نمایش خودکار: " . ($ls['enabled']
            ? ('روشن ✅ — ' . ($ls['mode'] === 'always' ? 'هر بار /start' : 'فقط بار اول'))
            : 'خاموش') . "\n";
        $cap .= "زبان‌های فعال: " . (empty($on) ? '—' : implode('، ', $on)) . "\n";
        $cap .= "سرویس‌دهی به بقیه‌ی زبان‌ها: " . ($ls['blockOthers'] ? '<b>بسته</b> ⛔️' : 'باز') . "\n";
        if ($ls['blockOthers']) {
            $cap .= "\n⚠️ کاربری که زبانش جزو لیست بالا نباشه، پیام رد می‌گیره و هیچ بخشی از ربات براش کار نمی‌کنه. مدیرها هیچ‌وقت بسته نمی‌شن.\n";
        }
        // How many real users this refuses, right now. Without it an admin can
        // untick their own shop's language and lock out every customer with no
        // signal at all - which is exactly what happened once.
        $lsw_blocked = lang_switch_blocked_count();
        if ($lsw_blocked['blocked'] > 0) {
            $cap .= "\n🚨 <b>همین الان " . number_format($lsw_blocked['blocked']) . " کاربر از "
                . number_format($lsw_blocked['total']) . " کاربر ربات مسدودن</b> — زبانشون توی لیست بالا نیست.\n";
        } elseif ($ls['blockOthers']) {
            $cap .= "\n✅ همه‌ی " . number_format($lsw_blocked['total']) . " کاربر فعلی ربات، زبانشون توی لیست هست.\n";
        }
        if (!$ls['enabled']) {
            $cap .= "\nℹ️ منوی انتخاب زبان خودکار نشون داده نمی‌شه؛ کاربر فقط از دکمه‌ی «🌏 تغییر زبان» توی منوی اصلی می‌تونه عوضش کنه (اگه اون دکمه روشن باشه).\n";
        }
        list($prevCap) = language_picker_payload();
        $cap .= "\n👁 <b>چیزی که کاربر می‌بینه:</b>\n" . topup_packages_caption_preview_quote($prevCap);
        return $cap;
    }
}

if (!function_exists('limit_conflict_text')) {
    // A minimum above the maximum (or a maximum below the minimum) leaves no
    // amount a customer can pay. Returns the refusal to show, or null when the
    // value fits; 0 or empty on either side means "no limit" and never conflicts.
    function limit_conflict_text($isMin, $value, $other, $lang, $textbotlang)
    {
        if ((float) $value <= 0 || (float) $other <= 0 || ($isMin ? (float) $value <= (float) $other : (float) $value >= (float) $other)) {
            return null;
        }
        $code = currency_for_lang($lang);
        return strtr($textbotlang['Admin']['TopupPkg'][$isMin ? 'minAboveMax' : 'maxBelowMin'], [
            '{max}' => number_format((float) $other),
            '{min}' => number_format((float) $other),
            '{currency}' => currency_get($code)['title'] ?? $code,
        ]);
    }
}
if (!function_exists('gwfld_cancel_kb')) {
    // The ❌ on a "send me the new value" prompt. Without one the only way out
    // was to send something, so an admin who opened it by mistake had to type a
    // value to escape. Carries the settings screen's own message id, so
    // cancelling can redraw that screen where it stands.
    function gwfld_cancel_kb($lang, $key, $index, $screenId, $textbotlang)
    {
        return json_encode(['inline_keyboard' => [
            [[
                'text' => $textbotlang['Admin']['TopupPkg']['closeCaptionPromptBtn'],
                'callback_data' => "gwfldcancel:{$lang}:{$key}:{$index}:{$screenId}",
                'style' => 'danger',
            ]],
        ]]);
    }
}
