            }
            if (!empty($tp_bits)) {
                $tp_rep[] = '• ' . trim(strip_tags((string) gateway_group_label($tp_g, $textbotlang))) . ': ' . implode('، ', $tp_bits);
            }
        }
        if (!empty($tp_rep)) {
            $cap .= "\n\n<blockquote>📦 <b>بسته‌های تعریف‌شده</b>\n" . implode("\n", $tp_rep) . '</blockquote>';
        }
        return $cap;
    }
}
