if (!function_exists('topup_help_grid_rows')) {
    // shared grid builder for the رنگ/ایموجی/نام tool screens: every real
    // package (in its current order, columns_per_row-chunked) plus the fixed
    // custom/back pair on its own row, each button carrying
    // $cbPrefix:{lang}:{key}:{token} as its callback. $decorate, if given, is
    // called as fn(array $btn, array $style): array $btn to add tool-specific
    // visual extras (e.g. رنگ's state-circle suffix) - $style is the raw
    // package array for a real package, or the raw btnstyle array for
    // custom/back. چیدمان does NOT use this helper (see topup_help_layout_payload).
    function topup_help_grid_rows($lang, $key, $textbotlang, $cbPrefix, ?callable $decorate = null)
    {
        $pkgs = topup_packages_for($lang, $key, true);
        $cols = topup_columns_for($lang, $key);
        $rows = [];
        foreach (array_chunk($pkgs, $cols, true) as $rowPkgs) {
            $row = [];
            foreach ($rowPkgs as $i => $p) {
                $btn = topup_package_button($p, $lang, "{$cbPrefix}:{$lang}:{$key}:{$i}");
                if ($decorate !== null) {
                    $btn = $decorate($btn, $p);
                }
                $row[] = $btn;
            }
            $rows[] = $row;
        }
        $tp_customStyle = topup_btnstyle_for($lang, $key, 'custom', true);
        $tp_backStyle = topup_btnstyle_for($lang, $key, 'back', true);
        $customBtn = topup_styled_button($textbotlang['users']['Balance']['customAmountBtn'], $tp_customStyle, "{$cbPrefix}:{$lang}:{$key}:custom", 'primary');
        $backBtn = topup_styled_button($textbotlang['users']['Balance']['backToMethodBtn'], $tp_backStyle, "{$cbPrefix}:{$lang}:{$key}:back", 'danger');
        if ($decorate !== null) {
            $customBtn = $decorate($customBtn, $tp_customStyle);
            $backBtn = $decorate($backBtn, $tp_backStyle);
        }
        $rows[] = [$customBtn, $backBtn];
        return $rows;
    }
}
if (!function_exists('topup_help_color_payload')) {
    // single-tap color cycler, mirroring help_color_editor_payload exactly:
