if (!function_exists('topup_help_layout_payload')) {
    // چیدمان (renamed from جابه‌جایی): pick one real package, tap another to
    // swap - mirrors help_layout_editor_payload's pick/swap/cancel UX. Scoped
    // to real packages ONLY: custom/back are a fixed pair (always
    // custom-then-back), swapping them or swapping one with a package has no
    // sensible meaning, so they render here for context but carry a
    // non-actionable callback - unlike the other 3 tools this screen does
    // NOT reuse topup_help_grid_rows (that helper always makes custom/back
    // real tappable targets).
    function topup_help_layout_payload($lang, $key, $textbotlang, $selectedIdx = null)
    {
        $t = $textbotlang['Admin']['TopupPkg'];
        $pkgs = topup_packages_for($lang, $key, true);
        $cols = topup_columns_for($lang, $key);
        $pkgSelected = (is_int($selectedIdx) || ctype_digit((string) $selectedIdx)) ? (int) $selectedIdx : null;
        $rows = [];
        foreach (array_chunk($pkgs, $cols, true) as $rowPkgs) {
            $row = [];
            foreach ($rowPkgs as $i => $p) {
                $default = money($p['amount'] ?? '0', currency_for_lang($lang));
                $btn = topup_styled_button($default, $p, '');
                if ($pkgSelected !== null && $i === $pkgSelected) {
                    $btn['text'] = '🔵 ' . $btn['text'];
                    $btn['callback_data'] = "topuphelplaycancel:{$lang}:{$key}";
                } elseif ($pkgSelected !== null) {
                    $btn['callback_data'] = "topuphelplayswap:{$lang}:{$key}:{$pkgSelected}:{$i}";
                } elseif ($selectedIdx === 'custom' || $selectedIdx === 'back') {
                    // مبلغ دلخواه/بازگشت is pending - packages are not a
                    // valid swap target for it, so stay inert (symmetric
                    // with custom/back going inert while a package is picked)
                    $btn['callback_data'] = "topuphelplaynoop:{$lang}:{$key}";
                } else {
                    $btn['callback_data'] = "topuphelplaypick:{$lang}:{$key}:{$i}";
                }
                $row[] = $btn;
            }
            $rows[] = $row;
        }
        $tp_customStyle = topup_btnstyle_for($lang, $key, 'custom', true);
        $tp_backStyle = topup_btnstyle_for($lang, $key, 'back', true);
        $customBtn = topup_styled_button($textbotlang['users']['Balance']['customAmountBtn'], $tp_customStyle, '', 'primary');
        $backBtn = topup_styled_button($textbotlang['users']['Balance']['backToMethodBtn'], $tp_backStyle, '', 'danger');
        // مبلغ دلخواه/بازگشت are only ever swappable with EACH OTHER, never
        // with a real package - and a real package is only ever swappable
        // with another real package, never with these two
        if ($selectedIdx === 'custom') {
            $customBtn['text'] = '🔵 ' . $customBtn['text'];
            $customBtn['callback_data'] = "topuphelplaycancel:{$lang}:{$key}";
            $backBtn['callback_data'] = "topuphelplayswap:{$lang}:{$key}:custom:back";
        } elseif ($selectedIdx === 'back') {
            $backBtn['text'] = '🔵 ' . $backBtn['text'];
            $backBtn['callback_data'] = "topuphelplaycancel:{$lang}:{$key}";
            $customBtn['callback_data'] = "topuphelplayswap:{$lang}:{$key}:back:custom";
        } elseif ($selectedIdx === null) {
            $customBtn['callback_data'] = "topuphelplaypick:{$lang}:{$key}:custom";
            $backBtn['callback_data'] = "topuphelplaypick:{$lang}:{$key}:back";
        } else {
            $customBtn['callback_data'] = "topuphelplaynoop:{$lang}:{$key}";
            $backBtn['callback_data'] = "topuphelplaynoop:{$lang}:{$key}";
        }
        $pair = [$customBtn, $backBtn];
        if (topup_custom_back_swapped($lang, $key)) {
            $pair = array_reverse($pair);
        }
        $rows[] = $pair;
        $fullWidthBtn = ['text' => $t['fullWidthBtn'], 'callback_data' => "topuphelpfullwidth:{$lang}:{$key}"];
        if ($cols === 1) {
            $fullWidthBtn['style'] = 'success';
        }
        $rows[] = [$fullWidthBtn];
        $rows[] = [['text' => $t['backBtn'], 'callback_data' => "topuphelphub:{$lang}:{$key}"]];
        return json_encode(['inline_keyboard' => $rows]);
    }
}
if (!function_exists('topup_minmax_payload')) {
    function topup_minmax_payload($lang, $key, $textbotlang)
    {
        $t = $textbotlang['Admin']['TopupPkg'];
        [$min, $max] = topup_minmax_for($lang, $key);
        $cur = currency_for_lang($lang);
        // a gateway with a dollar floor shows that floor as its minimum, not
        // whatever smaller number happens to be stored - that is what the
        // customer is actually held to
        $floor = topup_usd_floor_toman($lang, $key);
        $curTitle = currency_get($cur)['title'] ?? $cur;
        if ($floor !== null && ($min === null || (float) $min <= $floor)) {
            $minText = strtr($t['minUsdFloorText'], ['{price}' => number_format($floor), '{currency}' => $curTitle]);
        } else {
            // same as the ceiling below: a gateway has a floor whether or not
            // this screen was ever used, so "no limit" would be a lie
            $effMin = $min !== null ? $min : topup_gateway_min($lang, $key);
            $minText = $effMin !== null ? money($effMin, $cur) : $t['noLimit'];
        }
        // same for the ceiling: an online gateway has one whether or not this
        // screen was ever used, so saying "unlimited" here would be a lie
        $effMax = $max !== null ? $max : topup_gateway_max($lang, $key);
        $maxText = $effMax !== null ? money($effMax, $cur) : $t['noLimit'];
        $cap = strtr($floor !== null ? $t['minmaxCaptionOnline'] : $t['minmaxCaption'], ['{min}' => $minText, '{max}' => $maxText]);
        // this screen sets limits and nothing else - styling the buttons of the
        // amount flow lives in 🎨 → 💳 درگاه‌ها, one place instead of two
        $kb = json_encode(['inline_keyboard' => [
            [['text' => $t['setMinBtn'], 'callback_data' => "topupminset:{$lang}:{$key}", 'style' => 'primary']],
            [['text' => $t['setMaxBtn'], 'callback_data' => "topupmaxset:{$lang}:{$key}", 'style' => 'primary']],
            // reachable from 🏦 بسته‌های شارژ and from 🎨 → 💳 درگاه‌ها, so it
            // returns to whichever of the two actually opened this gateway
            [['text' => $t['backToPrevBtn'], 'callback_data' => topup_owner_screen_cb($lang, $key), 'style' => 'danger']],
        ]]);
        return [$cap, $kb];
    }
}
if (!function_exists('gw_field_value_text')) {
    // What one setting currently resolves to for this language, and whether it
    // is the language's own value or inherited from the global 💎 مالی setup.
    function gw_field_value_text($field, $lang, $textbotlang)
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        if (gw_field_scope($field) === 'global') {
            // one value for the whole bot: never "own", never green, and read
            // straight from PaySetting because that is what the payment code
            // itself reads (pay_value would invent a per-language layer the
            // gateway integrations do not honour)
            $raw = (string) getPaySettingValue($field['field']);
            if ($raw === '') {
                return [false, $t['notSet']];
            }
            return [false, mb_strlen($raw) > 22 ? mb_substr($raw, 0, 10) . '…' . mb_substr($raw, -6) : $raw];
        }
        $own = gw_pay_override_has($field['field'], $lang);
        $raw = (string) pay_value($field['field'], $lang, '');
        if ($raw === '') {
            return [$own, $t['notSet']];
        }
        if ($field['type'] === 'money') {
            $shown = money($raw, currency_for_lang($lang));
        } else {
            $shown = mb_strlen($raw) > 22 ? mb_substr($raw, 0, 10) . '…' . mb_substr($raw, -6) : $raw;
        }
        return [$own, $own ? $shown : sprintf($t['inheritedAs'], $shown)];
    }
}
if (!function_exists('gateway_settings_payload')) {
    function gateway_settings_payload($lang, $key, $textbotlang)
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        $kb = ['inline_keyboard' => []];
        // Deliberately no on/off button on this screen. The single ✅/❌ in the
        // hub is the one switch an admin should think about, and it now drives
        // both the per-language allow-list and the global one. Repeating it here
        // (twice - once per language, once global) was the whole confusion.
        foreach (gw_field_registry()[$key] ?? [] as $i => $field) {
            if ($field['type'] === 'cards') {
                // deliberately no suffix here at all - the card list has its
                // own screen where count/detail actually belongs
                $btn = ['text' => $t[$field['label']], 'callback_data' => "gwcards:{$lang}"];
                if ($key === 'card') {
                    $btn['style'] = 'primary';
                }
                $kb['inline_keyboard'][] = [$btn];
                continue;
            }
            list($own, $shown) = gw_field_value_text($field, $lang, $textbotlang);
            $btn = [
                // the 🌐 marks a value shared between languages - on a gateway
                // that only exists in Persian there is no second language for
                // it to mean anything against, so it is left off there
                'text' => (gw_field_scope($field) === 'global' && !gateway_single_lang($key) ? $t['globalFieldPrefix'] : '')
                    . $t[$field['label']] . ' — ' . $shown,
                'callback_data' => "gwfld:{$lang}:{$key}:{$i}",
            ];
            if ($key === 'card') {
                // no green-for-customised here - every field on this screen
                // is blue no matter what; which fields ARE customised is
                // reported as a blockquote in gateway_settings_caption()
                // instead (see the $key==='card' block there).
                $btn['style'] = 'primary';
            } elseif ($own) {
                $btn['style'] = 'success';
            }
            $kb['inline_keyboard'][] = [$btn];
        }
        if ($key === 'card') {
            // global (not per-language, like CartDirect above) - one bot-wide
            // switch, same reasoning as the on/off switch note at the top of
            // this function: one thing to think about, not one per language.
            // Sits outside gw_field_registry() on purpose since that registry
            // has no boolean-toggle field type yet and this is the only field
            // that needs one - not worth widening a system 8 other gateways
            // share for a single one-off switch.
            $cardToggleSetting = select("setting", "cardRandomAmount, smsForwardEnabled", null, null, "select");
            $randOn = (($cardToggleSetting['cardRandomAmount'] ?? '0') === '1');
            $smsFwdOn = (($cardToggleSetting['smsForwardEnabled'] ?? '0') === '1');
            // locked ON while SMS Forward is active - matching an SMS to an
            // invoice only works if every invoice's amount is unique, so
            // turning random-amount off out from under an active SMS Forward
            // setup would silently break matching. Routed to a separate
            // no-op callback (cardrandlocked:) instead of reusing
            // cardrandtoggle: so tapping it always explains why, rather than
            // either silently doing nothing or (worse) toggling anyway.
            // Blue always, on or off - the ✅ prefix carries the state.
            $kb['inline_keyboard'][] = [[
                'text' => ($randOn ? '✅ ' : '') . '🎲 مبلغ رندوم برای هر فاکتور' . ($smsFwdOn ? ' 🔒' : ''),
                'callback_data' => $smsFwdOn ? "cardrandlocked:{$lang}" : "cardrandtoggle:{$lang}",
                'style' => 'primary',
            ]];
            $kb['inline_keyboard'][] = [[
                'text' => ($smsFwdOn ? '✅ ' : '') . '📲 SMS Forward',
                'callback_data' => "smsfwdset:{$lang}",
                'style' => 'primary',
            ]];
            $kb['inline_keyboard'][] = [[
                'text' => '🔧 تنظیمات فنی درگاه (این زبان)',
                'callback_data' => "cardlegacy:{$lang}",
                'style' => 'primary',
            ]];
        }
        if ($key === 'ton') {
            // green once the memo shape has been changed from the factory one,
            // same signal every other customised row on these screens uses
            $kb['inline_keyboard'][] = [[
                'text' => '🏷 تنظیمات ممو (تگ)',
                'callback_data' => "tonmemo:{$lang}",
                'style' => topup_memo_is_custom($lang, 'ton') ? 'success' : 'primary',
            ]];
        }
        if ($key === 'frenzyex') {
            // a copy button, not a callback one: this address is only ever
            // pasted into FrenzyEx's own panel, so tapping it should put it on
            // the clipboard rather than navigate anywhere. Same copy_text shape
            // the TRX/TON invoices already use for their wallet addresses.
            $kb['inline_keyboard'][] = [[
                'text' => '📋 کپی آدرس کال‌بک',
                'copy_text' => ['text' => frenzyex_callback_url()],
            ]];
        }
        $legacy = gw_legacy_settings_datain($key);
        if ($legacy !== null) {
            // "(مشترک بین همه زبان‌ها)" is true of this screen everywhere except
            // on a gateway that has only one language - there it just confuses
            $legacyLabel = gateway_single_lang($key)
                ? ($t['legacyBtnSingle'] ?? $t['legacyBtn'])
                : $t['legacyBtn'];
            $kb['inline_keyboard'][] = [['text' => $legacyLabel, 'callback_data' => $legacy]];
        }
        if (gw_has_any_override($key, $lang)) {
            $kb['inline_keyboard'][] = [['text' => $t['resetBtn'], 'callback_data' => "gwrst:{$lang}:{$key}"]];
        }
        // back goes to the screen this gateway was actually opened from: a
        // grouped gateway is only reachable through its group, so returning to
        // the hub would skip a level and lose the admin's place
        $gwGroup = gateway_group_of($key);
        $kb['inline_keyboard'][] = [[
            'text' => $t['backBtn'],
            'callback_data' => $gwGroup !== null ? "gwgroup:{$lang}:{$gwGroup}" : "gwlang:{$lang}",
            'style' => 'danger',
        ]];
        return json_encode($kb);
    }
}
if (!function_exists('ton_memo_settings_payload')) {
    // What the TON invoice's comment is built out of. Two parts are settable
    // (a shop prefix and the length of the random part); the customer's id and
    // username are shown as locked rows rather than left out entirely, so that
    // tapping one answers "why can't I use this?" in place - the same 🔒 +
    // explaining-callback pattern the card gateway's locked switches use.
    function ton_memo_settings_caption($lang)
    {
        $cfg = topup_memo_config($lang, 'ton');
        $lim = topup_memo_limits();
        $sample = $cfg['prefix'] . str_repeat('x', (int) $cfg['len']);
        $out = "<blockquote><b>🏷 تنظیمات ممو (تگ) — TON</b></blockquote>\n\n";
        $out .= "ممو همان کامنتی است که مشتری همراه تراکنش می‌فرستد و ربات پرداخت را از روی آن می‌شناسد.\n\n";
        $out .= "🔤 <b>پیشوند:</b> " . ($cfg['prefix'] === '' ? '<i>ندارد</i>' : "<code>{$cfg['prefix']}</code>") . "\n";
        $out .= "🎲 <b>طول بخش تصادفی:</b> <b>{$cfg['len']}</b> کاراکتر\n\n";
        $out .= "👁 <b>نمونه:</b> <code>{$sample}</code>\n\n";
        $out .= "<blockquote>پیشوند فقط حروف انگلیسی و عدد می‌پذیرد (حداکثر {$lim['prefixMax']} کاراکتر) و بخش تصادفی بین {$lim['lenMin']} تا {$lim['lenMax']} کاراکتر است. "
            . "بخش تصادفی حذف‌شدنی نیست؛ تنها چیزی است که فاکتورها را از هم جدا می‌کند.</blockquote>\n\n";
        $out .= "<blockquote>🔒 <b>چرا آیدی و یوزرنیم کاربر در دسترس نیست؟</b>\n"
