        }
        if (in_array('hashbad', $has, true)) {
            $out .= "\n\n" . $t['captionPreviewHashBadLabel'] . "\n"
                . topup_packages_caption_preview_quote(topup_gwcap_for('hashbad', $lang, $key, $textbotlang));
        }
        if (in_array('paidalert', $has, true)) {
            $out .= "\n\n" . $t['captionPreviewPaidAlertLabel'] . "\n"
                . topup_packages_caption_preview_quote(topup_gwcap_for('paidalert', $lang, $key, $textbotlang));
        }
        if (in_array('invoice', $has, true)) {
            $out .= "\n\n" . $t['captionPreviewInvoiceLabel'] . "\n"
                . topup_packages_caption_preview_quote(topup_gwcap_for('inv', $lang, $key, $textbotlang));
        }
        if (in_array('expired', $has, true)) {
            $out .= "\n\n" . $t['captionPreviewExpiredLabel'] . "\n"
                . topup_packages_caption_preview_quote(topup_gwcap_for('exp', $lang, $key, $textbotlang));
        }
        return $out;
    }
}
if (!function_exists('topup_gw_group_payload')) {
    // one family's gateways, mirroring the group screens in 💎 مالی so the two
    // sections read the same way
    function topup_gw_group_payload($lang, $group, $textbotlang)
    {
        $registry = gateway_registry($textbotlang);
        $rows = [];
        foreach (gateway_group_members($group, $lang) as $key) {
            $rows[] = [[
                'text' => $registry[$key] ?? $key,
                'callback_data' => "topupgw:{$lang}:{$key}",
                'style' => 'primary',
            ]];
        }
        $rows[] = [['text' => $textbotlang['Admin']['GatewayLang']['backBtn'], 'callback_data' => "topupgwlist:{$lang}", 'style' => 'danger']];
        $rows[] = [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
        $cap = strtr($textbotlang['Admin']['TopupPkg']['gwGroupCaption'], [
            '{group}' => gateway_group_label($group, $textbotlang),
            '{lang}' => $textbotlang['bottext']['langs'][$lang] ?? $lang,
        ]);
        return [$cap, json_encode(['inline_keyboard' => $rows])];
    }
}
if (!function_exists('topup_gw_list_payload')) {
    // every gateway, card-to-card included: it also has its own shortcut button
    // on the 💰 screen, but listing it here too keeps this one place where the
    // whole set can be walked through
    function topup_gw_list_payload($lang, $textbotlang)
    {
        $rows = [];
        $shown = [];
        foreach (gateway_registry($textbotlang) as $key => $label) {
            if (!gateway_applicable_for_lang($key, $lang)) {
                continue;
            }
            // same families as 💎 مالی → 💳 درگاه‌های پرداخت, drawn at the
            // position of their first visible member so the order matches
            $group = gateway_group_of($key);
            if ($group !== null) {
                if (isset($shown[$group])) {
                    continue;
                }
                $shown[$group] = true;
                $rows[] = [[
                    'text' => gateway_group_label($group, $textbotlang),
                    'callback_data' => "topupgwgrp:{$lang}:{$group}",
                    'style' => 'primary',
                ]];
                continue;
            }
            $rows[] = [[
                'text' => $label,
                'callback_data' => "topupgw:{$lang}:{$key}",
                'style' => 'primary',
            ]];
        }
        $rows[] = [['text' => $textbotlang['Admin']['GatewayLang']['backBtn'], 'callback_data' => "bt_group|{$lang}|topup", 'style' => 'danger']];
        $rows[] = [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'bt_close', 'style' => 'danger']];
        $cap = strtr($textbotlang['Admin']['TopupPkg']['gwListCaption'], [
            '{lang}' => $textbotlang['bottext']['langs'][$lang] ?? $lang,
        ]);
        return [$cap, json_encode(['inline_keyboard' => $rows])];
    }
}
if (!function_exists('card_invoice_btncolor_payload')) {
    function card_invoice_btncolor_payload($lang, $textbotlang)
    {
        $styleEmoji = ['' => '⚪', 'primary' => '🔵', 'success' => '🟢', 'danger' => '🔴'];
        $rows = [];
        foreach (card_invoice_btnstyle_items($textbotlang, $lang) as $which => $defaultLabel) {
            $style = card_invoice_btnstyle_for($lang, $which);
            // preview with the same effective colour the customer will see, so
            // "not picked yet" shows this button's built-in default rather than
            // a white swatch that never actually appears on the invoice
            $color = card_invoice_btnstyle_color($lang, $which);
            $btn = topup_styled_button($defaultLabel, $style, "cardbtncolpick:{$lang}:{$which}", $color);
            $btn['text'] .= ' ' . ($styleEmoji[$color] ?? '⚪');
            $rows[] = [$btn];
        }
        $rows[] = [['text' => $textbotlang['Admin']['GatewayLang']['backBtn'], 'callback_data' => "cardbtn:{$lang}"]];
        return json_encode(['inline_keyboard' => $rows]);
    }
}
if (!function_exists('card_invoice_btnrename_payload')) {
    function card_invoice_btnrename_payload($lang, $textbotlang)
    {
        $styleEmoji = ['' => '⚪', 'primary' => '🔵', 'success' => '🟢', 'danger' => '🔴'];
        $rows = [];
        foreach (card_invoice_btnstyle_items($textbotlang, $lang) as $which => $defaultLabel) {
            $style = card_invoice_btnstyle_for($lang, $which);
            $btn = topup_styled_button($defaultLabel, $style, "cardbtnrenpick:{$lang}:{$which}");
            if (trim((string) ($style['label'] ?? '')) !== '') {
                $btn['text'] .= ' ✏️';
            }
            // the colour this button actually renders with - the rename screen
            // showed no hint of it, so an admin had to leave and open 🎨 to know
            $btn['text'] .= ' ' . ($styleEmoji[card_invoice_btnstyle_color($lang, $which)] ?? '⚪');
            $rows[] = [$btn];
        }
        $rows[] = [['text' => $textbotlang['Admin']['BtnStyle']['resetRenameBtn'], 'callback_data' => "cardbtnrenreset:{$lang}"]];
        $rows[] = [['text' => $textbotlang['Admin']['GatewayLang']['backBtn'], 'callback_data' => "cardbtn:{$lang}"]];
        return json_encode(['inline_keyboard' => $rows]);
    }
}
if (!function_exists('card_invoice_btnlayout_payload')) {
    // 📐 چیدمان for the copy-card rows: how many of them share a keyboard row.
    // Only reachable with 2+ cards, since one button has nothing to arrange.
    // Same tap-to-select / tap-to-swap editor the 💳 package layout uses: the
    // copy buttons are drawn in their REAL grid with their real colours and
    // names, so what the admin arranges is what the customer will see.
    function card_invoice_btnlayout_payload($lang, $textbotlang, $selectedIdx = null)
    {
        $cards = card_invoice_ordered_cards($lang);
        $total = count($cards);
        $perRow = card_invoice_copy_perrow($lang);
        $sel = (is_int($selectedIdx) || ctype_digit((string) $selectedIdx)) ? (int) $selectedIdx : null;
        if ($sel !== null && ($sel < 0 || $sel >= $total)) {
            $sel = null;
        }
        $btns = [];
        foreach ($cards as $i => $c) {
            $which = card_invoice_copy_key($i + 1);
            $style = card_invoice_btnstyle_for($lang, $which);
            $label = trim((string) ($style['label'] ?? '')) !== ''
                ? $style['label']
                : card_invoice_copy_label($i + 1, $total, $textbotlang);
            $btn = ['text' => $label];
            $color = card_invoice_btnstyle_color($lang, $which);
            if ($color !== '') {
                $btn['style'] = $color;
            }
            if ($sel !== null && $i === $sel) {
                $btn['text'] = '🔵 ' . $btn['text'];
                $btn['callback_data'] = "cardbtnlaycancel:{$lang}";
            } elseif ($sel !== null) {
                $btn['callback_data'] = "cardbtnlayswap:{$lang}:{$sel}:{$i}";
            } else {
                $btn['callback_data'] = "cardbtnlaypick:{$lang}:{$i}";
            }
            $btns[] = $btn;
        }
        $rows = array_chunk($btns, max(1, $perRow));
        $fullBtn = ['text' => $textbotlang['Admin']['Help']['toggleWidthBtn'], 'callback_data' => "cardbtnlayfull:{$lang}"];
        if ($perRow === 1) {
            $fullBtn['style'] = 'success';
        }
        $rows[] = [$fullBtn];
        $rows[] = [['text' => $textbotlang['Admin']['Help']['resetLayoutBtn'], 'callback_data' => "cardbtnlayreset:{$lang}"]];
        $rows[] = [['text' => $textbotlang['Admin']['GatewayLang']['backBtn'], 'callback_data' => "cardbtn:{$lang}", 'style' => 'danger']];
        return json_encode(['inline_keyboard' => $rows]);
    }
}
if (!function_exists('gateway_settings_caption')) {
    function gateway_settings_caption($lang, $key, $textbotlang)
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        $cur = currency_for_lang($lang);
        $cap = strtr($t['setCaption'], [
            '{gateway}' => gateway_registry($textbotlang)[$key] ?? $key,
            '{lang}' => $textbotlang['bottext']['langs'][$lang] ?? $lang,
            '{currency}' => currency_get($cur)['title'] ?? $cur,
        ]);
        if ($key === 'card') {
            // the shared template's middle sentence describes the green/
            // colorless convention every OTHER gateway still uses - wrong for
            // card, where every button is blue and customisation is reported
            // as a blockquote below instead (see the $key==='card' block).
            $cap = str_replace(
                'دکمه‌های رنگی یعنی این زبون مقدار اختصاصی خودشو داره، بدون‌رنگ یعنی از تنظیمات کلی 💎 مالی میاد.',
                'موارد اختصاصی این زبون پایین همین پیام، به صورت گزارش نشون داده می‌شن.',
                $cap
            );
        }
        $hasGlobal = false;
        foreach (gw_field_registry()[$key] ?? [] as $f) {
            if (gw_field_scope($f) === 'global') {
                $hasGlobal = true;
            }
        }
        // same reason as the 🌐 prefix in gateway_settings_payload(): a
        // Persian-only gateway has no other language to share the value with,
        // so this sentence only puzzles the admin reading it
        if ($hasGlobal && !gateway_single_lang($key)) {
            $cap .= "\n\n" . $t['globalFieldHint'];
        }
        if (!gateway_globally_on($key)) {
            $cap .= "\n\n" . $t['globallyOffWarn'];
        }
        if ($key === 'card') {
            // every field on this screen is blue no matter what (no more
            // green-for-customised buttons) - what's actually been changed
            // from default is reported here instead, as a blockquote.
            $report = [];
            foreach (gw_field_registry()['card'] as $f) {
                if ($f['type'] === 'cards') {
                    if (gw_cards_has_override($lang)) {
                        $report[] = "• {$t[$f['label']]}: اختصاصی این زبان";
                    }
                } elseif (gw_field_scope($f) === 'global') {
                    if ((string) getPaySettingValue($f['field']) !== '') {
                        $report[] = "• {$t[$f['label']]}: تنظیم شده";
                    }
                } elseif (gw_pay_override_has($f['field'], $lang)) {
                    $report[] = "• {$t[$f['label']]}: اختصاصی این زبان";
                }
            }
            if (!empty($report)) {
                $cap .= "\n\n<blockquote>📝 گزارش موارد تغییریافته:\n" . implode("\n", $report) . '</blockquote>';
            }
        }
        if ($key === 'frenzyex') {
            // the one value that has to travel OUT of this bot: FrenzyEx's own
            // panel is where the completion webhook gets registered, so the
            // address belongs on the screen the admin is already looking at
            $cap .= "\n\n" . sprintf($textbotlang['Admin']['gateway']['frenzyExCallbackUrl'], frenzyex_callback_url());
        }
        // every gateway, card included: the numbers that are actually in force
        $cap .= gateway_effective_report($lang, $key, $textbotlang);
        return $cap;
    }
}
if (!function_exists('gateway_effective_report')) {
    // "What will this gateway actually use right now?" - as a quote under its
    // settings screen.
    //
    // The buttons above it can only say ست نشده, which is not the same thing as
    // "nothing happens": an unset invoice lifetime still expires after 30
    // minutes and an unset range still holds the customer to 100..1,000,000.
    // Those defaults were invisible, so an admin had to read the code to learn
    // what their own shop does. Every line here names the number AND where it
    // came from.
    function gateway_effective_report($lang, $key, $textbotlang)
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        $src = function ($field) use ($lang) {
            if (gw_pay_override_has($field, $lang)) {
                return 'اختصاصی این زبان';
            }
            $row = select("PaySetting", "ValuePay", "NamePay", $field, "select");
            $global = is_array($row) ? trim((string) ($row['ValuePay'] ?? '')) : '';
            return $global !== '' ? 'تنظیم کلی' : 'پیش‌فرض';
        };
        $lines = [];
        foreach (gw_field_registry()[$key] ?? [] as $f) {
            if ($f['type'] === 'cards') {
                $n = count(gw_cards_for_lang($lang));
                $lines[] = "• {$t[$f['label']]}: " . ($n > 0 ? "{$n} کارت" : 'هیچ کارتی ثبت نشده ❌')
                    . (gw_cards_has_override($lang) ? ' (اختصاصی این زبان)' : '');
                continue;
            }
            // the invoice lifetime is the one number with a real default behind it
            if ($f['type'] === 'number' && $f['field'] === topup_expire_field($key)) {
                $lines[] = "• {$t[$f['label']]}: <b>" . topup_expire_minutes($lang, $key) . " دقیقه</b> ({$src($f['field'])})";
                continue;
            }
            // credentials and wallets: whether it is set, never the value itself
            if (gw_field_scope($f) === 'global') {
                $set = trim((string) getPaySettingValue($f['field'])) !== '';
            } else {
                $set = trim((string) pay_value($f['field'], $lang, '')) !== '';
            }
            $lines[] = "• {$t[$f['label']]}: " . ($set ? 'ثبت شده ✅' : 'ثبت نشده ❌');
        }
        // the deposit range lives in its own store, not in gw_field_registry -
        // but it is exactly the kind of number this report exists for
        [$min, $max] = topup_effective_limits($lang, $key);
        if ($min !== null || $max !== null) {
            $sfx = topup_gateway_paysetting_suffix($key);
            $cur = currency_get(currency_for_lang($lang))['title'] ?? '';
            // set in the top-up store, or in 💎 مالی, or neither
            [$storeMin] = topup_minmax_for($lang, $key);
            $gwMin = $sfx === null ? '' : trim((string) pay_value("minbalance{$sfx}", $lang, ''));
            $rangeSrc = ($storeMin !== null || $gwMin !== '') ? 'تنظیم شده' : 'پیش‌فرض';
            // only say "floored" when the floor is the number actually in
            // force - Stars has a one-star floor, but an admin who set 20,000
            // above it is being held to their own number, not to the floor
            $floor = topup_usd_floor_toman($lang, $key);
            $note = '';
            if ($floor !== null && $min !== null && (int) $min === (int) $floor) {
                $note = topup_has_usd_floor($key) ? ' — کف ۱ دلار' : ' — کف ۱ استار';
            }
            $lines[] = "• حداقل مبلغ: <b>" . ($min === null ? '—' : number_format((float) $min)) . " {$cur}</b> ({$rangeSrc}{$note})";
            $lines[] = "• حداکثر مبلغ: <b>" . ($max === null ? '—' : number_format((float) $max)) . " {$cur}</b>";
        }
        if (empty($lines)) {
            return '';
        }
        return "\n\n<blockquote>⚙️ <b>الان چی اعمال می‌شه</b>\n" . implode("\n", $lines) . '</blockquote>';
    }
}
if (!function_exists('gateway_cards_payload')) {
    function gateway_cards_payload($lang, $textbotlang, $mode = 'view', array $selected = [])
    {
        $t = $textbotlang['Admin']['GatewayLang'];
        $own = gw_cards_has_override($lang);
        $cards = gw_cards_for_lang($lang);
        $kb = ['inline_keyboard' => []];

        if ($mode === 'delete') {
            foreach ($cards as $i => $c) {
                $name = $c['name'] !== '' ? ' — ' . $c['name'] : '';
                $kb['inline_keyboard'][] = [[
                    'text' => (in_array($i, $selected, true) ? '✅ ' : '⬜️ ') . $c['number'] . $name,
                    'callback_data' => "gwcdeltog:{$lang}:{$i}",
                ]];
            }
            $kb['inline_keyboard'][] = [['text' => $t['cardDeleteConfirmBtn'], 'callback_data' => "gwcdelconfirm:{$lang}", 'style' => 'danger']];
            $kb['inline_keyboard'][] = [['text' => $t['cardCancelBtn'], 'callback_data' => "gwcards:{$lang}"]];
            return json_encode($kb);
        }

        if ($mode === 'edit') {
            foreach ($cards as $i => $c) {
                $name = $c['name'] !== '' ? ' — ' . $c['name'] : '';
                $kb['inline_keyboard'][] = [['text' => $c['number'] . $name, 'callback_data' => "gwcedit:{$lang}:{$i}"]];
            }
            $kb['inline_keyboard'][] = [['text' => $t['cardCancelBtn'], 'callback_data' => "gwcards:{$lang}"]];
            return json_encode($kb);
        }

        // view (default) - read-only rows, deletion/editing happen through
        // their own dedicated modes rather than a tap-to-delete row
        foreach ($cards as $i => $c) {
            $name = $c['name'] !== '' ? ' — ' . $c['name'] : '';
            $kb['inline_keyboard'][] = [['text' => ($own ? '' : '🔒 ') . $c['number'] . $name, 'callback_data' => 'none']];
        }
        $kb['inline_keyboard'][] = [['text' => $t['cardAddBtn'], 'callback_data' => "gwcadd:{$lang}"]];
        if ($own && !empty($cards)) {
            $kb['inline_keyboard'][] = [
                ['text' => $t['cardEditModeBtn'], 'callback_data' => "gwceditstart:{$lang}"],
                ['text' => $t['cardDeleteModeBtn'], 'callback_data' => "gwcdelstart:{$lang}"],
            ];
        }
        $kb['inline_keyboard'][] = [['text' => $t['backBtn'], 'callback_data' => "gwset:{$lang}:card"]];
        return json_encode($kb);
    }
}
