if (!function_exists('bulk_product_preview')) {
    // Renders the product list with the bot's own unit words rather than raw
    // codes. $maxChars caps the output so a 50-item batch cannot overflow
    // Telegram's message limit - the remainder is summarised instead.
    function bulk_product_preview($items, $textbotlang, $forceUnlimited = false, $maxChars = 0, $currencyCode = null)
    {
        $t = $textbotlang['Admin']['BulkProduct'];
        $gb = $textbotlang['common']['units']['gb'] ?? 'GB';
        $day = $textbotlang['common']['units']['dayShort'] ?? 'd';
        $unlimited = $textbotlang['common']['labels']['unlimited'] ?? '∞';
        $out = [];
        $used = 0;
        $shown = 0;
        $total = count($items);
        foreach (array_values($items) as $i => $it) {
            $vol = ($forceUnlimited || (string) $it['volume'] === '0') ? $unlimited : $it['volume'] . ' ' . $gb;
            $tim = ($forceUnlimited || (string) $it['time'] === '0') ? $unlimited : $it['time'] . ' ' . $day;
            $line = strtr($t['productLine'], [
                '{n}' => $i + 1,
                '{name}' => htmlspecialchars((string) $it['name'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'),
                '{price}' => money($it['price'], $currencyCode),
                '{volume}' => $vol,
                '{time}' => $tim,
            ]);
            if ($maxChars > 0 && $shown > 0 && $used + mb_strlen($line) > $maxChars) {
                $out[] = sprintf($t['andMore'], $total - $shown);
                break;
            }
            $out[] = $line;
            $used += mb_strlen($line) + 1;
            $shown++;
        }
        return implode("\n", $out);
    }
}
