if (!function_exists('panel_feature_keyboard')) {
    // Builds the ⚙️ panel-feature-status screen. Each feature is now ONE
    // tappable button carrying both its name and its state; the old layout
    // spent two buttons per feature, and the second one was always a dead
    // callback_data="none" label. Colour tracks state (green on / red off).
    // Both render sites - first open, and the re-render after a toggle - call
    // this, so the two copies can no longer drift apart.
    function panel_feature_keyboard($panel, $textbotlang)
    {
        $cv = json_decode($panel['customvolume'], true);
        if (!is_array($cv)) {
            $cv = [];
        }
        $type = $panel['type'];
        $code = $panel['code_panel'];
        $btn = function ($isOn, $label, $cb) {
            return [
                'text' => ($isOn ? '✅ ' : '❌ ') . $label,
                'callback_data' => $cb,
                'style' => $isOn ? 'success' : 'danger',
            ];
        };
        $rows = [];
        $rows[] = [$btn($panel['status'] == 'active', $textbotlang['keyboard']['showPanel'], "editpanel-statusbuy-{$panel['status']}-{$code}")];
        $rows[] = [$btn($panel['TestAccount'] == 'ONTestAccount', $textbotlang['keyboard']['showTestAccount'], "editpanel-statustest-{$panel['TestAccount']}-{$code}")];
        $rows[] = [['text' => $textbotlang['keyboard']['autoDeleteExpiredTest'], 'callback_data' => "editpanel-delusertestmenu-x-{$code}"]];
        // ibsng / mikrotik support only the three toggles above
        if (in_array($type, ["ibsng", "mikrotik"], true)) {
            return $rows;
        }
        $rows[] = [$btn($panel['status_extend'] == 'on_extend', $textbotlang['keyboard']['renewalStatus'], "editpanel-stautsextend-{$panel['status_extend']}-{$code}")];
        if (!in_array($type, ['Manualsale', "WGDashboard", 'hiddify'])) {
            $rows[] = [$btn($panel['config'] == 'onconfig', $textbotlang['keyboard']['sendConfig'], "editpanel-stautsconfig-{$panel['config']}-{$code}")];
            $rows[] = [$btn($panel['sublink'] == 'onsublink', $textbotlang['keyboard']['sendSubLink'], "editpanel-sublink-{$panel['sublink']}-{$code}")];
        }
        if (in_array($type, ['marzban', "x-ui_single", "marzneshin", "rebecca"])) {
            $rows[] = [['text' => $textbotlang['keyboard']['startTimingBuy'], 'callback_data' => "editpanel-onholdmenu-buy-{$code}"]];
            $rows[] = [['text' => $textbotlang['keyboard']['startTimingTest'], 'callback_data' => "editpanel-onholdmenu-test-{$code}"]];
        }
        if (!in_array($type, ["Manualsale", "WGDashboard"])) {
            $rows[] = [$btn($panel['changeloc'] == 'onchangeloc', $textbotlang['keyboard']['changeLocation'], "editpanel-changeloc-{$panel['changeloc']}-{$code}")];
            $rows[] = [$btn($panel['subvip'] == 'onsubvip', $textbotlang['keyboard']['exclusiveSubLink'], "editpanel-subvip-{$panel['subvip']}-{$code}")];
        }
        if (in_array($type, ["marzban"])) {
            $rows[] = [$btn($panel['inboundstatus'] == 'oninbounddisable', $textbotlang['keyboard']['inactiveAccount'], "editpanel-inbocunddisable-{$panel['inboundstatus']}-{$code}")];
        }
        // the three custom-service tiers belong together, so they share one
        // row; the caption explains what f / n / n2 mean
        $cvf = $cv['f'] ?? '0';
        $cvn = $cv['n'] ?? '0';
        $cvn2 = $cv['n2'] ?? '0';
        $rows[] = [
            $btn($cvf == '1', '♻️ f', "editpanel-customstatusf-{$cvf}-{$code}"),
            $btn($cvn == '1', '♻️ n', "editpanel-customstatusn-{$cvn}-{$code}"),
            $btn($cvn2 == '1', '♻️ n2', "editpanel-customstatusn2-{$cvn2}-{$code}"),
        ];
        return $rows;
    }
}
if (!function_exists('panel_onhold_submenu_keyboard')) {
