            $optNow['style'] = 'success';
        }
        $back = ['text' => $textbotlang['users']['backbtn'], 'callback_data' => "editpanel-onholdback-{$kind}-{$code}"];
        return ['inline_keyboard' => [[$optHold], [$optNow], [$back]]];
