if (!function_exists('product_currency_of')) {
    function product_currency_of($productId)
    {
        global $pdo;
        $q = $pdo->prepare("SELECT currency FROM product WHERE id = ? LIMIT 1");
        $q->execute([$productId]);
        $c = $q->fetchColumn();
        return ($c !== false && $c !== null && $c !== '') ? $c : currency_default_code();
    }
}
if (!function_exists('product_info_caption')) {
    // re-fetches + formats one product's info summary - reusable after every
    // field edit so the admin lands back on the SAME product's panel instead
    // of a generic menu, and can keep editing without re-navigating
    function product_info_caption($id_product, $agent, $locationName, $textbotlang)
    {
        global $pdo;
        $q = $pdo->prepare("SELECT * FROM product WHERE id = ? AND agent = ? AND (Location = ? OR Location = '/all') LIMIT 1");
        $q->bindValue(1, $id_product, PDO::PARAM_STR);
        $q->bindValue(2, $agent, PDO::PARAM_STR);
        $q->bindValue(3, $locationName, PDO::PARAM_STR);
        $q->execute();
        $info_product = $q->fetch(PDO::FETCH_ASSOC);
        if (!$info_product) {
            return null;
        }
        $count_invoice = select("invoice", "*", "name_product", $info_product['name_product'], "count");
        return sprintf($textbotlang['Admin']['Product']['editSummary'], $info_product['name_product'], money($info_product['price_product'], $info_product['currency'] ?? null), $info_product['Volume_constraint'], $info_product['Location'], $info_product['Service_time'], $info_product['agent'], $info_product['data_limit_reset'], $info_product['note'], $info_product['category'], $count_invoice);
    }
}
if (!function_exists('help_layout_back_cb')) {
    // where the layout/color/emoji/rename tool screens' "back" button goes:
    // the tutorial system's own sub-hubs for its two kinds, or the new
    // button-styling per-kind sub-hub for everything else (panel/product/category)
    function help_layout_back_cb($kind, $lang)
    {
        // :bt - since 📚 مدیریت آموزش‌ها stopped carrying its own copy of the
        // display hub, 🎨 شخصی‌سازی ← 📚 پیام و دکمه‌های آموزش is the only way
        // into these two screens, so this is where their chain has to end up.
        // Without it, backing out of the colour/layout/emoji tools dropped the
        // admin into 📚 مدیریت آموزش‌ها, a menu they never came through.
        if ($kind === 'categories') {
            return "help_disp_cat:{$lang}:bt";
        }
        if ($kind === 'tutorials') {
            return "help_disp_tut:{$lang}:bt";
        }
        return "btnstyle_kindhub:{$kind}:{$lang}";
    }
}
