            ['text' => $tx['keyboard']['userNote'], 'callback_data' => "statusnamecustomf"],
        ];
        $rows[] = [
            ['text' => $bulkbuy_v == 'onbulk' ? $on : $off, 'callback_data' => $tog('bulkbuy', $bulkbuy_v)],
            ['text' => $tx['keyboard']['bulkPurchaseStatus'], 'callback_data' => "bulkbuy"],
        ];
        $rows[] = [
