if (!function_exists('feature_section_effective')) {
    // The four ⚙️ تنظیمات sub-screens of 🌐 وضعیت قابلیت‌ها (هر زبان). Each
    // value is read through feature_setting_value(), so a language nobody has
    // touched still shows (and the bot still uses) the original global value.
    // Keys are stable strings - they are what the per-language store is keyed
    // by and what the value prompts carry in their callback_data.
    function feature_section_effective($lang)
    {
        $setting = select("setting", "*", null, null, "select");
        $aff = select("affiliates", "*", null, null, "select");
        $limit = json_decode((string) $setting['limitnumber'], true);
        if (!is_array($limit)) {
            $limit = [];
        }
        return [
            'aff_percent' => feature_setting_value('aff_percent', $lang, (string) $setting['affiliatespercentage']),
            'aff_giftamount' => feature_setting_value('aff_giftamount', $lang, (string) $aff['price_Discount']),
            'aff_commission' => feature_setting_value('aff_commission', $lang, (string) $aff['status_commission']),
            'aff_startgift' => feature_setting_value('aff_startgift', $lang, (string) $aff['Discount']),
            'aff_firstbuy' => feature_setting_value('aff_firstbuy', $lang, (string) $aff['porsant_one_buy']),
            'aff_banner_text' => feature_setting_value('aff_banner_text', $lang, (string) $aff['description']),
            'aff_banner_media' => feature_setting_value('aff_banner_media', $lang, (string) $aff['id_media']),
            'wheel_price' => feature_setting_value('wheel_price', $lang, (string) $setting['wheelـluck_price']),
            'loc_limit_all' => feature_setting_value('loc_limit_all', $lang, (string) ($limit['all'] ?? 0)),
            'loc_limit_free' => feature_setting_value('loc_limit_free', $lang, (string) ($limit['free'] ?? 0)),
            'phone_prefix' => implode(',', phone_prefixes_for_lang($lang)),
        ];
    }
}
if (!function_exists('feature_section_of_key')) {
    // which of the four sections a value key belongs to - the value prompts
    // only carry the key, and the screen to return to has to be derivable
    // from it. null means "not a key this screen owns", i.e. ignore.
    function feature_section_of_key($key)
    {
        $map = [
            'aff_percent' => 'aff',
            'aff_giftamount' => 'aff',
            'aff_banner' => 'aff',
            'wheel_price' => 'wheel',
            'loc_limit_all' => 'loc',
            'loc_limit_free' => 'loc',
            'app_name' => 'linkapp',
            'app_link' => 'linkapp',
            'phone_prefix' => 'phone',
        ];
        return $map[$key] ?? null;
    }
}
if (!function_exists('feature_phone_prefix_label')) {
    // "+98" / "+7 / +375" / "any country" - an unset language really does
    // accept every country, so it needs wording rather than an empty gap
    function feature_phone_prefix_label($lang, $sectionTexts)
    {
        $p = phone_prefixes_for_lang($lang);
        if (!$p) {
            return $sectionTexts['phoneAny'] ?? 'any';
        }
        return implode(' / ', array_map(function ($x) {
            return '+' . $x;
        }, $p));
    }
}
if (!function_exists('feature_section_caption')) {
    function feature_section_caption($textbotlang, $lang, $section)
    {
        $tx = lang_tab_texts($lang);
        $v = feature_section_effective($lang);
        $langName = $tx['bottext']['langs'][$lang] ?? $lang;
        $s = $tx['Admin']['FeatureSection'];
        // amounts belong to this language's currency (setting.lang_currency),
        // so they are rendered with its symbol/decimals rather than as a bare
        // number the admin would read as toman
        $cur = currency_for_lang($lang);
        if ($section === 'linkapp') {
            $rows = app_rows_for_lang($lang);
            $list = '';
            foreach ($rows as $r) {
                // a row with no language of its own is shown to every language,
                // so say so - editing or deleting it here hits all of them
                $shared = ($r['lang'] === null || $r['lang'] === '' || $r['lang'] === 'all');
                $list .= "\n• " . ($shared ? '🌍 ' : '') . htmlspecialchars($r['name'], ENT_QUOTES, 'UTF-8');
            }
            if ($list === '') {
                $list = "\n" . $s['appNone'];
            }
            return strtr($s['appTitle'], ['{lang}' => $langName, '{list}' => $list]);
        }
        if ($section === 'phone') {
            return strtr($s['phoneTitle'], [
                '{lang}' => $langName,
                '{prefixes}' => feature_phone_prefix_label($lang, $s),
            ]);
        }
        if ($section === 'wheel') {
            return strtr($s['wheelTitle'], ['{lang}' => $langName, '{price}' => money($v['wheel_price'], $cur)]);
        }
        if ($section === 'aff') {
            return strtr($s['affTitle'], [
                '{lang}' => $langName,
                '{percent}' => (string) $v['aff_percent'],
                '{gift}' => money($v['aff_giftamount'], $cur),
            ]);
        }
        return strtr($s['locTitle'], [
            '{lang}' => $langName,
            '{all}' => (string) $v['loc_limit_all'],
            '{free}' => (string) $v['loc_limit_free'],
        ]);
    }
}
if (!function_exists('feature_section_payload')) {
    function feature_section_payload($textbotlang, $lang, $section)
    {
        $tx = lang_tab_texts($lang);
        $s = $tx['Admin']['FeatureSection'];
        $v = feature_section_effective($lang);
        $on = $tx['Admin']['Status']['statuson'];
        $off = $tx['Admin']['Status']['statusoff'];
        $cur = currency_for_lang($lang);
        $rows = [];
        if ($section === 'linkapp') {
            foreach (app_rows_for_lang($lang) as $r) {
                $shared = ($r['lang'] === null || $r['lang'] === '' || $r['lang'] === 'all');
                $rows[] = [
                    ['text' => '✏️ ' . ($shared ? '🌍 ' : '') . $r['name'], 'callback_data' => "flsappe:{$lang}:{$r['id']}"],
                    ['text' => '🗑', 'callback_data' => "flsappd:{$lang}:{$r['id']}", 'style' => 'danger'],
                ];
            }
            $rows[] = [['text' => $s['appAdd'], 'callback_data' => "flsask:{$lang}:app_name", 'style' => 'success']];
        } elseif ($section === 'phone') {
            $rows[] = [['text' => strtr($s['phonePrefixBtn'], ['{prefixes}' => feature_phone_prefix_label($lang, $s)]), 'callback_data' => "flsask:{$lang}:phone_prefix"]];
        } elseif ($section === 'wheel') {
            $rows[] = [['text' => strtr($s['wheelPriceBtn'], ['{price}' => money($v['wheel_price'], $cur)]), 'callback_data' => "flsask:{$lang}:wheel_price"]];
        } elseif ($section === 'aff') {
            $rows[] = [['text' => strtr($s['affPercentBtn'], ['{percent}' => (string) $v['aff_percent']]), 'callback_data' => "flsask:{$lang}:aff_percent"]];
            $rows[] = [['text' => strtr($s['affGiftBtn'], ['{gift}' => money($v['aff_giftamount'], $cur)]), 'callback_data' => "flsask:{$lang}:aff_giftamount"]];
            $rows[] = [['text' => $s['affBannerBtn'], 'callback_data' => "flsask:{$lang}:aff_banner"]];
            $comOn = $v['aff_commission'] === 'oncommission';
            $rows[] = [
                ['text' => $comOn ? $on : $off, 'callback_data' => "flstog:{$lang}:aff_commission:{$v['aff_commission']}", 'style' => $comOn ? 'success' : 'danger'],
                ['text' => $s['affCommissionBtn'], 'callback_data' => "none"],
            ];
            $giftOn = $v['aff_startgift'] === 'onDiscountaffiliates';
            $rows[] = [
                ['text' => $giftOn ? $on : $off, 'callback_data' => "flstog:{$lang}:aff_startgift:{$v['aff_startgift']}", 'style' => $giftOn ? 'success' : 'danger'],
                ['text' => $s['affStartGiftBtn'], 'callback_data' => "none"],
            ];
            $firstOn = $v['aff_firstbuy'] === 'on_buy_porsant';
            $rows[] = [
                ['text' => $firstOn ? $on : $off, 'callback_data' => "flstog:{$lang}:aff_firstbuy:{$v['aff_firstbuy']}", 'style' => $firstOn ? 'success' : 'danger'],
                ['text' => $s['affFirstBuyBtn'], 'callback_data' => "none"],
            ];
        } else {
            $rows[] = [['text' => strtr($s['locAllBtn'], ['{all}' => (string) $v['loc_limit_all']]), 'callback_data' => "flsask:{$lang}:loc_limit_all"]];
            $rows[] = [['text' => strtr($s['locFreeBtn'], ['{free}' => (string) $v['loc_limit_free']]), 'callback_data' => "flsask:{$lang}:loc_limit_free"]];
            $rows[] = [['text' => $s['locResetBtn'], 'callback_data' => "flsloc:{$lang}:ask", 'style' => 'danger']];
        }
        $rows[] = [['text' => $s['back'], 'callback_data' => "fls_lang:{$lang}"]];
        return json_encode(['inline_keyboard' => $rows]);
    }
}
if (!function_exists('displayhub_payload')) {
    function displayhub_payload($textbotlang)
    {
        // LangScope moved out to its own شاپ reply-keyboard button (shop
        // catalog visibility belongs with the rest of the shop settings, not
        // here) - this handler and its callback (displayhub_open:langscope)
        // are left in place, just unreachable from this screen now
        return json_encode(['inline_keyboard' => [
            [['text' => $textbotlang['Admin']['BtnStyle']['hubBtn'], 'callback_data' => 'displayhub_open:btnstyle']],
            // this hub is opened from the bottext message list now, so it needs
            // its own way back there, on top of the plain-close row it already
            // had. btnstyle_hub_payload() a few lines below already hardcodes
            // 'fa' regardless of context, so returning to the 'fa' tab here
            // matches an existing, accepted simplification rather than
            // introducing a new one.
            [['text' => $textbotlang['bottext']['backToListLabel'], 'callback_data' => 'btact|back|fa']],
            [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'displayhub_close', 'style' => 'danger']],
        ]]);
    }
}
if (!function_exists('btnstyle_hub_payload')) {
    // top screen of "🎨 شخصی‌سازی نمایش دکمه‌ها": language tabs + the three
    // commerce kinds this tool covers (panels/products/categories)
    function btnstyle_hub_payload($lang, $textbotlang)
    {
        $kb = ['inline_keyboard' => []];
        $kb['inline_keyboard'][] = [
            ['text' => ($lang == 'fa' ? "✅" : "") . $textbotlang['bottext']['langs']['fa'], 'callback_data' => "btnstyle_lang:fa"],
            ['text' => ($lang == 'en' ? "✅" : "") . $textbotlang['bottext']['langs']['en'], 'callback_data' => "btnstyle_lang:en"],
            ['text' => ($lang == 'ru' ? "✅" : "") . $textbotlang['bottext']['langs']['ru'], 'callback_data' => "btnstyle_lang:ru"],
            ['text' => ($lang == 'zh' ? "✅" : "") . $textbotlang['bottext']['langs']['zh'], 'callback_data' => "btnstyle_lang:zh"],
            ['text' => ($lang == 'tk' ? "✅" : "") . $textbotlang['bottext']['langs']['tk'], 'callback_data' => "btnstyle_lang:tk"],
        ];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['panelsBtn'], 'callback_data' => "btnstyle_kindhub:panel:{$lang}"]];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['productsBtn'], 'callback_data' => "btnstyle_kindhub:product:{$lang}"]];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['categoriesBtn'], 'callback_data' => "btnstyle_kindhub:category:{$lang}"]];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['backToHubBtn'], 'callback_data' => 'displayhub_back']];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['bottext']['btn_close'], 'callback_data' => 'btnstyle_close', 'style' => 'danger']];
        return json_encode($kb);
    }
}
if (!function_exists('btnstyle_kindhub_payload')) {
    // per-kind sub-hub: the four style tools (layout/color/emoji/rename),
    // all reusing the same generic engine the tutorial system's buttons use
    function btnstyle_kindhub_payload($kind, $lang, $textbotlang)
    {
        $kb = ['inline_keyboard' => []];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['Help']['layoutBtn'], 'callback_data' => "help_lay:{$kind}:{$lang}"]];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['Help']['colorBtn'], 'callback_data' => "help_col:{$kind}:{$lang}"]];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['Help']['emojiBtn'], 'callback_data' => "help_emo:{$kind}:{$lang}"]];
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['BtnStyle']['renameBtn'], 'callback_data' => "help_ren:{$kind}:{$lang}"]];
        // grouping is a layout choice about these exact buttons, so it belongs
        // here rather than in 💎 مالی - and only the payment methods have
        // families to be grouped into
        if ($kind === 'gateway') {
            $kb['inline_keyboard'][] = [[
                'text' => $textbotlang['Admin']['BtnStyle']['groupMethodsBtn'],
                'callback_data' => "gwgrp:{$lang}",
                'style' => topup_group_methods_on($lang) ? 'success' : 'primary',
            ]];
        }
        // each kind goes back where it was opened from: gateway styling is
        // reached from 🎨 → 💰, the language picker's from 🌐 تنظیمات تغییر زبان,
        // and the rest from 🛒 پیام‌های مراحل خرید
        if ($kind === 'langpick') {
            $back = 'bt_langswitch';
        } elseif ($kind === 'gateway') {
            $back = "bt_group|{$lang}|topup";
        } else {
            $back = "bt_group|{$lang}|buyflow";
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['LangScope']['backToHubBtn'], 'callback_data' => $back]];
        return json_encode($kb);
    }
}
if (!function_exists('topup_group_hub_payload')) {
    // ---- 🗂 دسته‌بندی درگاه‌ها ----
    // Sits with the other tools that decide how the payment-method buttons look,
    // because that is what it is: a layout choice about those exact buttons.
    // Everything it owns - the switch, the family screen's caption, and the
    // family buttons' own colour and name - lives on this one screen.
    function topup_group_hub_payload($lang, $textbotlang)
    {
        $t = $textbotlang['Admin']['BtnStyle'];
        $on = topup_group_methods_on($lang);
        $rows = [];
        $rows[] = [[
            'text' => $on ? $t['groupMethodsOnBtn'] : $t['groupMethodsOffBtn'],
            'callback_data' => "gwgrptog:{$lang}",
            'style' => $on ? 'success' : 'primary',
        ]];
        $rows[] = [
            ['text' => $t['defaultGroupCaptionBtn'], 'callback_data' => "gwgrpcapdefault:{$lang}"],
            [
                'text' => $t['editGroupCaptionBtn'],
                'callback_data' => "gwgrpcap:{$lang}",
                'style' => topup_group_caption_has_override($lang) ? 'success' : 'primary',
            ],
        ];
        // a white, non-navigating label: the rows under it are buttons, not texts
        $rows[] = [['text' => $t['groupBtnsLabel'], 'callback_data' => "gwgrpsep:{$lang}"]];
        $rows[] = [['text' => $textbotlang['Admin']['Help']['colorBtn'], 'callback_data' => "gwgrpcol:{$lang}"]];
        $rows[] = [['text' => $t['renameBtn'], 'callback_data' => "gwgrpren:{$lang}"]];
        $rows[] = [['text' => $textbotlang['Admin']['LangScope']['backToHubBtn'], 'callback_data' => "btnstyle_kindhub:gateway:{$lang}", 'style' => 'danger']];
        $cap = strtr($t['groupMethodsCaption'], [
            '{lang}' => $textbotlang['bottext']['langs'][$lang] ?? $lang,
            '{state}' => $on ? $t['groupMethodsStateOn'] : $t['groupMethodsStateOff'],
        ]);
        $cap .= "\n\n" . $t['groupCaptionPreviewLabel'] . "\n"
            . topup_packages_caption_preview_quote(strtr(
                topup_group_caption_for($lang, $textbotlang['users']['Balance']['groupMethodCaption']),
                ['{group}' => gateway_group_label('online', $textbotlang)]
            ));
        return [$cap, json_encode(['inline_keyboard' => $rows])];
    }
    function topup_group_color_payload($lang, $textbotlang)
    {
        $styleEmoji = ['' => '⚪', 'primary' => '🔵', 'success' => '🟢', 'danger' => '🔴'];
        $rows = [];
        foreach (array_keys(gateway_groups()) as $group) {
            $style = topup_group_btnstyle_for($lang, $group);
            $btn = topup_styled_button(gateway_group_label($group, $textbotlang), $style, "gwgrpcolpick:{$lang}:{$group}", 'primary');
            $color = (string) ($style['color'] ?? '');
            $btn['text'] .= ' ' . ($styleEmoji[$color !== '' ? $color : 'primary'] ?? '⚪');
            $rows[] = [$btn];
        }
        $rows[] = [['text' => $textbotlang['Admin']['GatewayLang']['backBtn'], 'callback_data' => "gwgrp:{$lang}", 'style' => 'danger']];
        return json_encode(['inline_keyboard' => $rows]);
    }
    function topup_group_rename_payload($lang, $textbotlang)
    {
        $rows = [];
        foreach (array_keys(gateway_groups()) as $group) {
            $style = topup_group_btnstyle_for($lang, $group);
            $btn = topup_styled_button(gateway_group_label($group, $textbotlang), $style, "gwgrprenpick:{$lang}:{$group}", 'primary');
            if (trim((string) ($style['label'] ?? '')) !== '') {
                $btn['text'] .= ' ✏️';
            }
            $rows[] = [$btn];
        }
        $rows[] = [['text' => $textbotlang['Admin']['BtnStyle']['resetRenameBtn'], 'callback_data' => "gwgrprenreset:{$lang}"]];
        $rows[] = [['text' => $textbotlang['Admin']['GatewayLang']['backBtn'], 'callback_data' => "gwgrp:{$lang}", 'style' => 'danger']];
        return json_encode(['inline_keyboard' => $rows]);
    }
}
if (!function_exists('btnstyle_kindhub_caption_key')) {
    function btnstyle_kindhub_caption_key($kind)
    {
        if ($kind === 'panel') {
            return 'panelsSubCaption';
        }
        if ($kind === 'product') {
            return 'productsSubCaption';
        }
        if ($kind === 'category') {
            return 'categoriesSubCaption';
        }
        return 'gatewaysSubCaption';
    }
}
if (!function_exists('help_rename_editor_payload')) {
    // live list of items; tapping one prompts a text replacement for the
    // name shown to end users (the real DB name/identity never changes) -
    // mirrors help_emoji_editor_payload's pick-then-prompt flow exactly
    function help_rename_editor_payload($lang, $kind, $textbotlang)
    {
        $items = help_layout_items($lang, $kind);
        $section = help_layout_section($lang, $kind);
        $orderedKeys = help_layout_apply_order(array_keys($items), $section['order']);
        $backCb = help_layout_back_cb($kind, $lang);
        $kb = ['inline_keyboard' => []];
        if (empty($orderedKeys)) {
            $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['Help']['layoutEmpty'], 'callback_data' => $backCb]];
        } else {
            $buttonsByKey = [];
            foreach ($orderedKeys as $idx => $key) {
                $emo = help_layout_emoji_prefix($key, $section);
                $color = help_layout_effective_color($section, $key, $kind);
                $isRenamed = isset($section['rename'][$key]) && $section['rename'][$key] !== '';
                // 🚫 = hidden from customers (set in 📐 چیدمان) - shown here too,
                // or renaming a button nobody can see looks like a broken rename
                $name = (!empty($section['hidden'][(string) $key]) ? '🚫 ' : '') . $emo['prefix'] . ($items[$key] ?? $key) . ($isRenamed ? ' ✏️' : '');
                $btn = ['text' => $name, 'callback_data' => "help_ren_pick:{$kind}:{$lang}:{$idx}"];
                if ($emo['icon'] !== '') {
                    $btn['icon_custom_emoji_id'] = $emo['icon'];
                }
                if ($color !== '') {
                    $btn['style'] = $color;
                }
                $buttonsByKey[$key] = $btn;
            }
            $rows = help_layout_grouped_rows($kind, $lang, $orderedKeys, $buttonsByKey, $section, $textbotlang);
            foreach ($rows as $row) {
                $kb['inline_keyboard'][] = $row;
            }
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['BtnStyle']['resetRenameBtn'], 'callback_data' => "help_ren_reset:{$kind}:{$lang}"]];
        $kb['inline_keyboard'][] = [['text' => help_layout_back_label($kind, $textbotlang), 'callback_data' => $backCb]];
        return json_encode($kb);
    }
}
if (!function_exists('help_layout_editor_payload')) {
    // generic layout editor for the end-user-facing category / tutorial-name
    // buttons: pick an item, tap another to swap positions (mirrors
    // layout_editor_payload's pick/swap/cancel UX), plus a full/half width
    // toggle for the selected item. $kind is 'categories' or 'tutorials'.
    // Shows the item's current emoji + color too, so this is always an
    // honest live preview, not just a partial one.
    function help_layout_editor_payload($lang, $kind, $textbotlang, $selectedIdx = null)
    {
        $items = help_layout_items($lang, $kind);
        $section = help_layout_section($lang, $kind);
        $orderedKeys = help_layout_apply_order(array_keys($items), $section['order']);
        $backCb = help_layout_back_cb($kind, $lang);
        $kb = ['inline_keyboard' => []];
        if (empty($orderedKeys)) {
            $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['Help']['layoutEmpty'], 'callback_data' => $backCb]];
        } else {
            $buttonsByKey = [];
            foreach ($orderedKeys as $idx => $key) {
                $emo = help_layout_emoji_prefix($key, $section);
                $color = help_layout_effective_color($section, $key, $kind);
                // hidden items keep their row here (this is the only screen that
                // can bring them back) and say so
                $name = (!empty($section['hidden'][(string) $key]) ? '🚫 ' : '') . $emo['prefix'] . ($items[$key] ?? $key);
                $isSel = ($selectedIdx !== null && (string) $selectedIdx === (string) $idx);
                if ($isSel) {
                    $btn = ['text' => '🔵 ' . $name, 'callback_data' => "help_lay_cancel:{$kind}:{$lang}"];
                } elseif ($selectedIdx !== null) {
                    $btn = ['text' => $name, 'callback_data' => "help_lay_swap:{$kind}:{$lang}:{$selectedIdx}:{$idx}"];
                } else {
                    $btn = ['text' => $name, 'callback_data' => "help_lay_pick:{$kind}:{$lang}:{$idx}"];
                }
                if ($emo['icon'] !== '') {
                    $btn['icon_custom_emoji_id'] = $emo['icon'];
                }
                if ($color !== '') {
                    $btn['style'] = $color;
                }
                $buttonsByKey[$key] = $btn;
            }
            $rows = help_layout_grouped_rows($kind, $lang, $orderedKeys, $buttonsByKey, $section, $textbotlang);
            foreach ($rows as $row) {
                $kb['inline_keyboard'][] = $row;
            }
            if ($selectedIdx !== null) {
                $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['Help']['toggleWidthBtn'], 'callback_data' => "help_lay_width:{$kind}:{$lang}:{$selectedIdx}"]];
                // show/hide for the selected item: a display switch, not a
                // delete - the item and its own on/off state are untouched
                $help_sel_key = $orderedKeys[$selectedIdx] ?? null;
                $help_sel_hidden = ($help_sel_key !== null && !empty($section['hidden'][(string) $help_sel_key]));
                $kb['inline_keyboard'][] = [[
                    'text' => $help_sel_hidden ? $textbotlang['Admin']['Help']['showBtn'] : $textbotlang['Admin']['Help']['hideBtn'],
                    'callback_data' => "help_lay_hide:{$kind}:{$lang}:{$selectedIdx}",
                    'style' => $help_sel_hidden ? 'success' : 'danger',
                ]];
            }
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['Help']['resetLayoutBtn'], 'callback_data' => "help_lay_reset:{$kind}:{$lang}"]];
        $kb['inline_keyboard'][] = [['text' => help_layout_back_label($kind, $textbotlang), 'callback_data' => $backCb]];
        return json_encode($kb);
    }
}

if (!function_exists('help_layout_grouped_rows')) {
    // The payment gateways are a dozen buttons in one flat run on all four
    // appearance screens (چیدمان / رنگ‌بندی / ایموجی / تغییر نام). They get the
    // same family headings 💳 کپشن و دکمه‌های درگاه‌ها already uses, so the same
    // set reads the same way wherever it is edited.
    //
    // Display only: the stored order is untouched, the order inside a family is
    // still the admin's own, and every other kind keeps its single list. The
    // headings are white labels that navigate nowhere.
    function help_layout_grouped_rows($kind, $lang, array $orderedKeys, array $buttonsByKey, array $section, $textbotlang)
    {
        if ($kind !== 'gateway' || !function_exists('gateway_disc_groups') || count($orderedKeys) < 2) {
            return help_layout_chunk_rows($orderedKeys, $buttonsByKey, $section['width']);
        }
        $rows = [];
        $placed = [];
        foreach (array_keys(gateway_disc_groups()) as $group) {
            $members = [];
            foreach ($orderedKeys as $k) {
                if (gateway_disc_group_of($k) === $group) {
                    $members[] = $k;
                    $placed[$k] = true;
                }
            }
            if (empty($members)) {
                continue;
            }
            $rows[] = [['text' => gateway_group_label($group, $textbotlang), 'callback_data' => "gwstylesep:{$lang}:{$group}"]];
            foreach (help_layout_chunk_rows($members, $buttonsByKey, $section['width']) as $r) {
                $rows[] = $r;
            }
        }
        // a gateway added later that no family claims still has to show up
        $rest = [];
        foreach ($orderedKeys as $k) {
            if (empty($placed[$k])) {
                $rest[] = $k;
            }
        }
        if (!empty($rest)) {
            $rows[] = [['text' => $textbotlang['Admin']['BtnStyle']['gwStyleOtherLabel'], 'callback_data' => "gwstylesep:{$lang}:other"]];
            foreach (help_layout_chunk_rows($rest, $buttonsByKey, $section['width']) as $r) {
                $rows[] = $r;
            }
        }
        return $rows;
    }
}
if (!function_exists('help_layout_effective_color')) {
    // The colour a button will ACTUALLY render with for the end user, so every
    // preview screen here shows the same thing the customer sees. Payment-method
    // buttons fall back to blue (gateway_apply_button_style does the same), the
    // other kinds still fall back to Telegram's plain white.
    function help_layout_effective_color(array $section, $key, $kind)
    {
        $color = $section['color'][$key] ?? '';
        if (in_array($color, ['primary', 'success', 'danger'], true)) {
            return $color;
        }
        return $kind === 'gateway' ? 'primary' : '';
    }
}
