if (!function_exists('help_preview_categories')) {
    // the categories a CUSTOMER would see, in the base (fa) strings the layout
    // settings are keyed by, with one representative row each so the label can
    // be resolved into the previewed language
    function help_preview_categories($rows, $lang)
    {
        $cats = [];
        foreach ($rows as $r) {
            $c = trim((string) ($r['category'] ?? ''));
            if ($c === '' || $c === '0' || isset($cats[$c])) {
                continue;
            }
            $view = help_resolve_lang($r, $lang);
            $cats[$c] = ($view['category'] !== '') ? $view['category'] : $c;
        }
        uksort($cats, 'strnatcasecmp');
        return $cats;
    }
}
if (!function_exists('help_preview_list_payload')) {
    // A real preview: the same grouping, order, width, emoji, colour and
    // hidden-ness the customer gets, built from the same help_layout_* helpers
    // index.php and keyboard.php render with. It used to be a flat list of raw
    // names, which told the admin nothing about what their display settings
    // actually did.
    function help_preview_list_payload($lang, $textbotlang, $catIdx = null)
    {
        $rows = select("help", "*", null, null, "fetchAll");
        if (!is_array($rows)) {
            $rows = [];
        }
        $ok = ['primary', 'success', 'danger'];
        $catSec = help_layout_section($lang, 'categories');
        $tutSec = help_layout_section($lang, 'tutorials');
        $cats = help_preview_categories($rows, $lang);
        $catKeys = array_keys($cats);
        $kb = ['inline_keyboard' => []];
        $hiddenCount = 0;

        // which tutorials belong on this screen
        $scope = [];
        if ($catIdx === null) {
            foreach ($rows as $r) {
                $c = trim((string) ($r['category'] ?? ''));
                if ($c === '' || $c === '0' || empty($cats)) {
                    $scope[] = $r;
                }
            }
        } else {
            $want = $catKeys[$catIdx] ?? null;
            foreach ($rows as $r) {
                if (trim((string) ($r['category'] ?? '')) === $want) {
                    $scope[] = $r;
                }
            }
        }

        // top screen with categories: the category buttons come first, exactly
        // as the customer sees them
        if ($catIdx === null && !empty($cats)) {
            $catBtns = [];
            foreach ($catKeys as $i => $base) {
                $emoji = $catSec['emoji'][$base] ?? '';
                $color = $catSec['color'][$base] ?? '';
                $catBtns[$base] = [
                    'text' => ($emoji !== '' ? $emoji . ' ' : '') . $cats[$base],
                    'callback_data' => "help_prev_cat:{$lang}:{$i}",
                    'style' => in_array($color, $ok, true) ? $color : 'primary',
                ];
            }
            $ordered = help_layout_visible(help_layout_apply_order(array_keys($catBtns), $catSec['order']), $catSec);
            $hiddenCount += count($catBtns) - count($ordered);
            $kb['inline_keyboard'] = array_merge($kb['inline_keyboard'], help_layout_chunk_rows($ordered, $catBtns, $catSec['width']));
        }

        // the tutorials of this screen, same treatment
        $tutBtns = [];
        foreach ($scope as $r) {
            $view = help_resolve_lang($r, $lang);
            $emoji = $tutSec['emoji'][(string) $r['id']] ?? '';
            $color = $tutSec['color'][(string) $r['id']] ?? '';
            $tutBtns[(string) $r['id']] = [
                'text' => ($emoji !== '' ? $emoji . ' ' : '') . $view['name'],
                'callback_data' => "help_prev_item:{$r['id']}:{$lang}" . ($catIdx === null ? '' : ":{$catIdx}"),
                'style' => in_array($color, $ok, true) ? $color : 'success',
            ];
        }
        $tutOrdered = help_layout_visible(help_layout_apply_order(array_keys($tutBtns), $tutSec['order']), $tutSec);
        $hiddenCount += count($tutBtns) - count($tutOrdered);
        $kb['inline_keyboard'] = array_merge($kb['inline_keyboard'], help_layout_chunk_rows($tutOrdered, $tutBtns, $tutSec['width']));

        if (empty($kb['inline_keyboard'])) {
            $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['Help']['emptyList'], 'callback_data' => 'none']];
        }
        if ($catIdx !== null) {
            $kb['inline_keyboard'][] = [['text' => '🔙 بازگشت به پیش‌نمایش', 'callback_data' => "help_preview:{$lang}", 'style' => 'danger']];
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['Admin']['Help']['backToListBtn'], 'callback_data' => "help_view_list:{$lang}", 'style' => 'danger']];
        return [json_encode($kb), $hiddenCount, count($cats), count($tutBtns)];
    }
}

if (!function_exists('help_set_lang_field')) {
    // writes tutorial fields for one language: 'fa' lands in the base columns,
    // every other language merges into the translations JSON blob (merge, not
    // overwrite, so name / category / content can be translated independently)
    function help_set_lang_field($id, $lang, array $fields)
    {
        $row = select("help", "*", "id", $id, "select");
        if ($row === false) {
            return false;
        }
        if ($lang === 'fa') {
            $map = [
                'name' => 'name_os',
                'category' => 'category',
                'description' => 'Description_os',
                'media' => 'Media_os',
                'media_type' => 'type_Media_os',
                'entities' => 'entities_os',
            ];
            foreach ($fields as $fk => $fv) {
                if (!isset($map[$fk])) {
                    continue;
                }
                update("help", $map[$fk], ($fk === 'entities') ? json_encode($fv) : $fv, "id", $id);
            }
            return true;
        }
        $tr = json_decode((string) ($row['translations'] ?? ''), true);
        if (!is_array($tr)) {
            $tr = [];
        }
        if (!isset($tr[$lang]) || !is_array($tr[$lang])) {
            $tr[$lang] = [];
        }
        foreach ($fields as $fk => $fv) {
            $tr[$lang][$fk] = $fv;
        }
        update("help", "translations", json_encode($tr, JSON_UNESCAPED_UNICODE), "id", $id);
        return true;
    }
}

if (!function_exists('help_item_menu_payload')) {
    function help_item_menu_payload($id, $lang, $textbotlang)
    {
        global $setting;
        $help_row = select("help", "*", "id", $id, "select");
        $L = $textbotlang['Admin']['Help'];
        if ($help_row === false) {
            $kb = ['inline_keyboard' => [[['text' => $L['backToListBtn'], 'callback_data' => "help_back:{$lang}"]]]];
            return ["⚠️", json_encode($kb)];
        }
        $help_tr = json_decode((string) ($help_row['translations'] ?? ''), true);
        $help_entry = ($lang !== 'fa' && is_array($help_tr) && isset($help_tr[$lang]) && is_array($help_tr[$lang])) ? $help_tr[$lang] : null;
        $help_view = help_resolve_lang($help_row, $lang);
        $help_cat_on = (isset($setting['categoryhelp']) && $setting['categoryhelp'] == "1");

        // raw (NOT fallback-resolved) values, so the admin sees exactly what is
        // and isn't set for the language they're currently editing
        if ($lang === 'fa') {
            $rawName = (string) $help_row['name_os'];
            $rawCat = (string) $help_row['category'];
            $rawDesc = (string) $help_row['Description_os'];
            $rawMedia = (string) $help_row['Media_os'];
            $rawMediaType = (string) $help_row['type_Media_os'];
        } else {
            $rawName = (string) ($help_entry['name'] ?? '');
            $rawCat = (string) ($help_entry['category'] ?? '');
            $rawDesc = (string) ($help_entry['description'] ?? '');
            $rawMedia = (string) ($help_entry['media'] ?? '');
            $rawMediaType = (string) ($help_entry['media_type'] ?? '');
        }

        $mediaLabels = ['photo' => $L['mediaPhoto'], 'video' => $L['mediaVideo'], 'document' => $L['mediaDocument']];
        $mediaTxt = ($rawMedia !== '' && isset($mediaLabels[$rawMediaType])) ? $mediaLabels[$rawMediaType] : $L['mediaNone'];

        $descTxt = $L['valueEmpty'];
        if ($rawDesc !== '') {
            $flat = trim(preg_replace('/\s+/u', ' ', $rawDesc));
            $descTxt = mb_substr($flat, 0, 60) . ((mb_strlen($flat) > 60) ? '…' : '');
        }

        $title = ($help_view['name'] !== '') ? $help_view['name'] : $help_row['name_os'];
        $info = "📚 <b>" . htmlspecialchars($title, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . "</b>\n";
        $info .= "━━━━━━━━━━━━━━━━━━\n";
        $info .= "🌐 " . ($textbotlang['bottext']['langs'][$lang] ?? $lang) . "\n";
        if ($lang === 'fa') {
            $info .= $L['itemStatusBase'] . "\n";
        } elseif ($help_entry !== null) {
            $info .= $L['itemStatusTranslated'] . "\n";
        } else {
            $info .= $L['itemStatusDefault'] . "\n";
        }
        $info .= "\n";
        $info .= $L['labelName'] . ": " . htmlspecialchars(($rawName !== '' ? $rawName : $L['valueEmpty']), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . "\n";
        if ($help_cat_on) {
            $catShow = ($rawCat !== '' && $rawCat !== '0') ? $rawCat : $L['valueEmpty'];
            $info .= $L['labelCategory'] . ": " . htmlspecialchars($catShow, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . "\n";
        }
        $info .= $L['labelContent'] . ": " . htmlspecialchars($descTxt, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . "\n";
        $info .= $L['labelMedia'] . ": " . $mediaTxt;

        $kb = ['inline_keyboard' => []];
        $rowTop = [['text' => $L['editNameBtn'], 'callback_data' => "help_name:{$id}:{$lang}"]];
        if ($help_cat_on) {
            $rowTop[] = ['text' => $L['editCategoryBtn'], 'callback_data' => "help_cat:{$id}:{$lang}"];
        }
        $kb['inline_keyboard'][] = $rowTop;
        $kb['inline_keyboard'][] = [['text' => $L['editContentBtn'], 'callback_data' => "help_edit:{$id}:{$lang}"]];
        if ($lang !== 'fa' && $help_entry !== null) {
            $kb['inline_keyboard'][] = [['text' => $L['resetLangBtn'], 'callback_data' => "help_reset:{$id}:{$lang}"]];
        }
        $kb['inline_keyboard'][] = [['text' => $textbotlang['keyboard']['deleteEducation'], 'callback_data' => "help_delete:{$id}:{$lang}", 'style' => 'danger']];
        $kb['inline_keyboard'][] = [['text' => $L['backToListBtn'], 'callback_data' => "help_back:{$lang}"]];
        return [$info, json_encode($kb)];
    }
}

