if ($text == "🎨 رنگ‌بندی دکمه‌ها" && $adminrulecheck['rule'] == "administrator") {
    sendmessage($from_id, "🎨 <b>بخش رنگ‌بندی دکمه‌های منوی اصلی</b>\n\nنوع کیبورد رو انتخاب کن 👇", $keyboard_colormanage, 'HTML');
