if (preg_match('/^layoutfull-(\d+)-(\d+)$/', $datain, $ly_m) && $adminrulecheck['rule'] == "administrator") {
    $ly_setting = select("setting", "*", null, null, "select");
    $ly_layout = json_decode($ly_setting['keyboardmain'], true);
    $ly_r = intval($ly_m[1]);
    $ly_c = intval($ly_m[2]);
    $ly_msg = "⚠️ دکمه پیدا نشد.";
    if (is_array($ly_layout) && isset($ly_layout['keyboard'][$ly_r][$ly_c])) {
        $ly_rows = $ly_layout['keyboard'];
        if (count($ly_rows[$ly_r]) >= 2) {
            $ly_newrows = [];
            foreach ($ly_rows[$ly_r] as $ly_b) {
                $ly_newrows[] = [$ly_b];
            }
            array_splice($ly_rows, $ly_r, 1, $ly_newrows);
            $ly_msg = "✅ ردیف شکسته شد — دکمه تمام‌عرض شد 🔲";
        } else {
            $ly_btn = $ly_rows[$ly_r][$ly_c];
            if (isset($ly_rows[$ly_r + 1]) && count($ly_rows[$ly_r + 1]) == 1) {
                $ly_rows[$ly_r + 1] = array_merge([$ly_btn], $ly_rows[$ly_r + 1]);
                array_splice($ly_rows, $ly_r, 1);
                $ly_msg = "✅ دکمه به ردیف پایین چسبید ◫";
            } elseif (isset($ly_rows[$ly_r - 1]) && count($ly_rows[$ly_r - 1]) == 1) {
                $ly_rows[$ly_r - 1] = array_merge($ly_rows[$ly_r - 1], [$ly_btn]);
                array_splice($ly_rows, $ly_r, 1);
                $ly_msg = "✅ دکمه به ردیف بالا چسبید ◫";
            } else {
                $ly_msg = "⚠️ ردیف‌های همسایه جای خالی ندارن (حداکثر ۲ دکمه توی هر ردیف).";
            }
        }
        $ly_layout['keyboard'] = array_values($ly_rows);
        update("setting", "keyboardmain", json_encode($ly_layout));
    }
    $ly_kb = layout_editor_payload($textbotlang);
    Editmessagetext($from_id, $message_id, $ly_msg . "\n\n📐 <b>چیدمان دکمه‌های منو</b> 👇", $ly_kb, 'HTML');
