if ($datain == "layoutreset" && $adminrulecheck['rule'] == "administrator") {
    $ly_setting = select("setting", "*", null, null, "select");
    $ly_layout = json_decode($ly_setting['keyboardmain'], true);
    $ly_default = [
        ['text_sell', 'text_extend'],
        ['text_usertest', 'text_wheel_luck'],
        ['text_Purchased_services', 'accountwallet'],
        ['addbalance'],
        ['text_affiliates', 'text_Tariff_list'],
        ['text_support', 'text_help'],
    ];
    $ly_bykey = [];
    if (is_array($ly_layout) && isset($ly_layout['keyboard']) && is_array($ly_layout['keyboard'])) {
        foreach ($ly_layout['keyboard'] as $ly_row) {
            foreach ((array) $ly_row as $ly_b) {
                if (is_array($ly_b) && isset($ly_b['text'])) {
                    $ly_bykey[$ly_b['text']] = $ly_b;
                }
            }
        }
    }
    $ly_newrows = [];
    foreach ($ly_default as $ly_drow) {
        $ly_nr = [];
        foreach ($ly_drow as $ly_k) {
            if (isset($ly_bykey[$ly_k])) {
                $ly_nr[] = $ly_bykey[$ly_k];
                unset($ly_bykey[$ly_k]);
            }
        }
        if (!empty($ly_nr)) {
            $ly_newrows[] = $ly_nr;
        }
    }
    foreach ($ly_bykey as $ly_b) {
        $ly_newrows[] = [$ly_b];
    }
    if (!is_array($ly_layout)) {
        $ly_layout = [];
    }
    $ly_layout['keyboard'] = $ly_newrows;
    update("setting", "keyboardmain", json_encode($ly_layout));
    $ly_kb = layout_editor_payload($textbotlang);
    Editmessagetext($from_id, $message_id, "🔄 چیدمان به پیش‌فرض برگشت (رنگ و ایموجی و استیکرها حفظ شدن)\n\n📐 <b>چیدمان دکمه‌های منو</b> 👇", $ly_kb, 'HTML');
