}
if (preg_match('/^btbbtntext-([a-z]{2})$/', (string) $user['step'], $btm) && $datain == '' && $adminrulecheck['rule'] == "administrator") {
    $bb_lang = $btm[1];
    $bb_newtext = trim((string) $text);
