    step('home', $from_id);
    list($bb_text, $bb_kb) = balancebtn_payload($bb_lang, $textbotlang);
    deletemessage($from_id, $message_id);
    sendmessage($from_id, $bb_msg . "\n\n" . $bb_text, $bb_kb, 'HTML');
