if (preg_match('/^volpct\|hub\|([a-z]{2})$/', $datain, $vp_m) && $adminrulecheck['rule'] == "administrator") {
    list($vp_text, $vp_kb) = volumepct_hub_payload($vp_m[1], $textbotlang);
