// the four typed fields of a CATEGORY's discount - the group twins of
// tpdautovalv / tpdautoexpv / tpdautolimitv / tpdautominv above, same
// validation, same "edit the screen you came from" ending
if (preg_match('/^dsgrp(val|exp|limit|min)v-([a-z]{2})-([a-z0-9_]+)$/', (string) $user['step'], $td_m) && $datain == '' && $adminrulecheck['rule'] == "administrator" && !topup_disc_is_nav_text($text, $textbotlang)) {
    $td_what = $td_m[1];
    $td_lang = $td_m[2];
    $td_group = $td_m[3];
    $td_raw = trim((string) $text);
    if ($td_what === 'min') {
        $td_raw = money_normalize($td_raw);
        if ($td_raw === null) {
            sendmessage($from_id, "⚠️ لطفاً فقط یه عدد بفرست 😅", $backadmin, 'HTML');
            return;
        }
    } elseif ($td_what === 'val') {
        if (!is_numeric($td_raw) || floatval($td_raw) < 0) {
            sendmessage($from_id, "⚠️ لطفاً فقط یه عدد بفرست 😅", $backadmin, 'HTML');
            return;
        }
    } elseif (!ctype_digit($td_raw)) {
        sendmessage($from_id, "⚠️ لطفاً فقط یه عدد بفرست 😅", $backadmin, 'HTML');
        return;
    }
    $td_g = topup_disc_group_for($td_lang, $td_group);
    if ($td_what === 'val') {
        if (($td_g['mode'] ?? 'percent') === 'percent' && floatval($td_raw) > 100) {
            sendmessage($from_id, "⚠️ درصد نمی‌تونه بیشتر از ۱۰۰ باشه 😅", $backadmin, 'HTML');
            return;
        }
        $td_g['value'] = floatval($td_raw);
        // typing a real value is the admin saying they want it live - the same
        // rule the per-gateway screen follows, for the same reason
        if (floatval($td_raw) > 0) {
            $td_wasOff = empty($td_g['enabled']);
            $td_g['enabled'] = true;
            // ...and turning the bulk one on clears the field, same as its own
            // on/off button does
            if ($td_group === 'all' && $td_wasOff) {
                topup_disc_group_set($td_lang, $td_group, $td_g);
                topup_disc_scope_disable_others($td_lang, 'all');
            }
        }
    } elseif ($td_what === 'min') {
        $td_g['minAmount'] = floatval($td_raw);
    } elseif ($td_what === 'exp') {
        $td_days = intval($td_raw);
        $td_g['expiry'] = $td_days > 0 ? (time() + $td_days * 86400) : 0;
    } else {
        $td_g['limitPerUser'] = intval($td_raw);
    }
    topup_disc_group_set($td_lang, $td_group, $td_g);
    step('home', $from_id);
    list($td_text, $td_kb) = topup_disc_group_auto_payload($td_lang, $td_group, $textbotlang);
    $td_mid = intval(json_decode((string) ($user['Processing_value'] ?? ''), true)['bt_msgid'] ?? 0);
    deletemessage($from_id, $message_id);
    $td_done = "✅ ذخیره شد!\n\n" . $td_text;
    if ($td_mid > 0) {
        Editmessagetext($from_id, $td_mid, $td_done, $td_kb, 'HTML');
    } else {
        sendmessage($from_id, $td_done, $td_kb, 'HTML');
    }
    return;
}
if (preg_match('/^tpdfld-(val|limit|user|exp|min)-([a-z]{2})-([a-z0-9_@]+)-(\d+)$/', (string) $user['step'], $td_m) && $datain == '' && $adminrulecheck['rule'] == "administrator" && !topup_disc_is_nav_text($text, $textbotlang)) {
    $td_what = $td_m[1];
    $td_lang = $td_m[2];
    $td_key = $td_m[3];
    $td_idx = (int) $td_m[4];
    $td_raw = trim((string) $text);
    if ($td_what === 'min') {
        // an amount: "5,000,000" and Persian digits are fine here
        $td_raw = money_normalize($td_raw) ?? $td_raw;
    }
    if (!is_numeric($td_raw) || floatval($td_raw) < 0) {
        sendmessage($from_id, "⚠️ لطفاً فقط یه عدد بفرست 😅", $backadmin, 'HTML');
        return;
    }
    $td_c = topup_disc_code_get($td_lang, $td_key, $td_idx);
    if ($td_what === 'val') {
        if (($td_c['mode'] ?? 'percent') === 'percent' && floatval($td_raw) > 100) {
            sendmessage($from_id, "⚠️ درصد نمی‌تونه بیشتر از ۱۰۰ باشه 😅", $backadmin, 'HTML');
            return;
        }
        topup_disc_code_update($td_lang, $td_key, $td_idx, floatval($td_raw) > 0
            ? ['value' => floatval($td_raw), 'enabled' => true]
            : ['value' => floatval($td_raw)]);
    } elseif ($td_what === 'limit') {
        topup_disc_code_update($td_lang, $td_key, $td_idx, ['limitTotal' => intval($td_raw)]);
    } elseif ($td_what === 'user') {
        topup_disc_code_update($td_lang, $td_key, $td_idx, ['limitPerUser' => intval($td_raw)]);
    } elseif ($td_what === 'min') {
        topup_disc_code_update($td_lang, $td_key, $td_idx, ['minAmount' => floatval($td_raw)]);
    } else {
        // days from now, 0 = never expires
        $td_days = intval($td_raw);
        topup_disc_code_update($td_lang, $td_key, $td_idx, ['expiry' => $td_days > 0 ? (time() + $td_days * 86400) : 0]);
    }
    step('home', $from_id);
    list($td_text, $td_kb) = topup_disc_code_payload($td_lang, $td_key, $td_idx, $textbotlang);
    $td_mid = intval(json_decode((string) ($user['Processing_value'] ?? ''), true)['bt_msgid'] ?? 0);
    deletemessage($from_id, $message_id);
    $td_done = "✅ ذخیره شد!\n\n" . $td_text;
    if ($td_mid > 0) {
        Editmessagetext($from_id, $td_mid, $td_done, $td_kb, 'HTML');
    } else {
        sendmessage($from_id, $td_done, $td_kb, 'HTML');
    }
    return;
}
