            return;
        }
        feature_setting_set('aff_banner_media', $fs_lang, $photoid);
        feature_setting_set('aff_banner_text', $fs_lang, (string) $caption);
    } elseif ($fs_key === 'app_name') {
        if (trim((string) $text) === '' || mb_strlen((string) $text) > 200) {
            sendmessage($from_id, $fs_tx['Admin']['apps']['nameTooLong'], null, 'HTML');
            return;
        }
        savedata("save", "fls_appname", $text);
        step("flsapplink", $from_id);
        sendmessage($from_id, $fs_tx['Admin']['apps']['askLink'], null, 'HTML');
        return;
    } elseif ($fs_key === 'app_link') {
        if (!filter_var($text, FILTER_VALIDATE_URL)) {
            sendmessage($from_id, $fs_tx['Admin']['managepanel']['invalidDomain'], null, 'HTML');
            return;
        }
        $fs_appid = (int) ($fs_data['fls_appid'] ?? 0);
        update("app", "link", $text, "id", $fs_appid);
    } elseif ($fs_key === 'phone_prefix') {
        // one or more country dial codes, e.g. "98" or "1,44"; a lone 0 clears
        // the restriction so the language accepts every country again
        $fs_clean = [];
        foreach (preg_split('/[,\s]+/', (string) $text) as $fs_p) {
            $fs_p = preg_replace('/\D+/', '', (string) $fs_p);
            if ($fs_p !== '' && $fs_p !== '0') {
                $fs_clean[] = $fs_p;
            }
        }
        if (!$fs_clean && trim((string) $text) !== '0') {
            sendmessage($from_id, $fs_tx['common']['invalidInput'], null, 'HTML');
            return;
        }
        // "0" is stored, not "": an empty value reads as "never set" and would
        // fall straight back to this language's built-in default
        feature_setting_set('phone_prefix', $fs_lang, $fs_clean ? implode(',', $fs_clean) : '0');
    } elseif ($fs_key === 'wheel_price' || $fs_key === 'aff_giftamount') {
        // an amount in this language's currency - USD/CNY/RUB/TMT carry
        // decimals, so "12.5" has to be accepted, not just whole numbers
        $fs_cur = currency_for_lang($fs_lang);
        if (!money_valid($text, $fs_cur)) {
            sendmessage($from_id, $fs_tx['common']['invalidInput'], null, 'HTML');
            return;
        }
        feature_setting_set($fs_key, $fs_lang, money_normalize($text));
    } else {
        // counts and percentages stay whole numbers
        if (!ctype_digit((string) $text)) {
            sendmessage($from_id, $fs_tx['common']['invalidInput'], null, 'HTML');
            return;
        }
        feature_setting_set($fs_key, $fs_lang, (string) intval($text));
    }
    step("home", $from_id);
    sendmessage($from_id, feature_section_caption($textbotlang, $fs_lang, $fs_sec), feature_section_payload($textbotlang, $fs_lang, $fs_sec), 'HTML');
