        update("topicid", "idreport", $createForumTopic['result']['message_thread_id'], "report", "paymentreport");
    }
    $createForumTopic = telegram('createForumTopic', [
        'chat_id' => $text,
        'name' => $textbotlang['Admin']['affiliates']['titleTopic']
    ]);
    if (!$createForumTopic['ok']) {
        $texterror = $textbotlang['Admin']['Channel']['botNotGroupAdmin'];
        sendmessage($from_id, $texterror, null, 'HTML');
        return;
    }

    if ($porsantreport != $createForumTopic['result']['message_thread_id']) {
        update("topicid", "idreport", $createForumTopic['result']['message_thread_id'], "report", "porsantreport");
    }
    $createForumTopic = telegram('createForumTopic', [
        'chat_id' => $text,
        'name' => $textbotlang['Admin']['report']['reportNight']
    ]);
    if (!$createForumTopic['ok']) {
        $texterror = $textbotlang['Admin']['Channel']['botNotGroupAdmin'];
        sendmessage($from_id, $texterror, null, 'HTML');
        return;
    }

    if ($reportnight != $createForumTopic['result']['message_thread_id']) {
        update("topicid", "idreport", $createForumTopic['result']['message_thread_id'], "report", "reportnight");
    }
    $createForumTopic = telegram('createForumTopic', [
        'chat_id' => $text,
        'name' => $textbotlang['Admin']['report']['reportCron']
    ]);
    if (!$createForumTopic['ok']) {
        $texterror = $textbotlang['Admin']['Channel']['botNotGroupAdmin'];
        sendmessage($from_id, $texterror, null, 'HTML');
        return;
    }

    if ($reportcron != $createForumTopic['result']['message_thread_id']) {
        update("topicid", "idreport", $createForumTopic['result']['message_thread_id'], "report", "reportcron");
    }
    $createForumTopic = telegram('createForumTopic', [
        'chat_id' => $text,
        'name' => $textbotlang['Admin']['report']['btnBackup']
    ]);
    if (!$createForumTopic['ok']) {
        $texterror = $textbotlang['Admin']['Channel']['botNotGroupAdmin'];
        sendmessage($from_id, $texterror, null, 'HTML');
        return;
    }

    if ($reportbackup != $createForumTopic['result']['message_thread_id']) {
        update("topicid", "idreport", $createForumTopic['result']['message_thread_id'], "report", "backupfile");
    }
    sendmessage($from_id, $textbotlang['Admin']['Channel']['setChannelReport'], $setting_panel, 'HTML');
    update("setting", "Channel_Report", $text);
    step('home', $from_id);
} elseif ($text == $textbotlang['keyboard']['shopSettings'] && $adminrulecheck['rule'] == "administrator") {
    sendmessage($from_id, $textbotlang['Admin']['shopSettingsCaption'], $shopkeyboard, 'HTML');
} elseif ($datain == "gwlang_hub" && $adminrulecheck['rule'] == "administrator") {
    gateway_lang_map(true);
    gw_lang_settings_map(true);
    Editmessagetext($from_id, $message_id, gateway_hub_caption('fa', $textbotlang), gateway_hub_payload('fa', $textbotlang), 'HTML');
} elseif ($datain == "gwlang_close" && $adminrulecheck['rule'] == "administrator") {
    deletemessage($from_id, $message_id);
} elseif (preg_match('/^gwlang:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    gw_lang_settings_map(true);
    Editmessagetext($from_id, $message_id, gateway_hub_caption($gw_m[1], $textbotlang), gateway_hub_payload($gw_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^gwtoggle:([a-z]{2}):([a-z0-9]+)(:1)?$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    $gw_lang = $gw_m[1];
    $gw_key = $gw_m[2];
    $gw_fromSettings = isset($gw_m[3]) && $gw_m[3] !== '';
    if (!in_array($gw_key, gateway_all_keys(), true)) {
        return;
    }
    $gw_keys = gateway_current_keys($gw_lang);
    if (in_array($gw_key, $gw_keys, true)) {
        // off for this language only - other languages may still be selling it
        $gw_keys = array_values(array_diff($gw_keys, [$gw_key]));
        gateway_set_for_lang($gw_lang, $gw_keys);
    } else {
        $gw_keys[] = $gw_key;
        gateway_set_for_lang($gw_lang, $gw_keys);
        // turning it on here has to turn on the separate global switch too,
        // otherwise the row shows ✅ while real users still see nothing and
        // there is no longer any second toggle on screen to discover
        gateway_globally_set($gw_key, true);
    }
    if ($gw_fromSettings) {
        Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_lang, $gw_key, $textbotlang), gateway_settings_payload($gw_lang, $gw_key, $textbotlang), 'HTML');
    } else {
        // stay on the screen the row was tapped on: a grouped gateway is only
        // listed inside its own group, so re-rendering the hub threw the admin
        // out of the family they were working in after every single toggle
        $gw_grp = gateway_group_of($gw_key);
        if ($gw_grp !== null) {
            Editmessagetext($from_id, $message_id, gateway_group_caption($gw_lang, $gw_grp, $textbotlang), gateway_group_payload($gw_lang, $gw_grp, $textbotlang), 'HTML');
        } else {
            Editmessagetext($from_id, $message_id, gateway_hub_caption($gw_lang, $textbotlang), gateway_hub_payload($gw_lang, $textbotlang), 'HTML');
        }
    }
} elseif (preg_match('/^gwall:([a-z]{2}):([01])$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if ($gw_m[2] === '1') {
        // "turn everything on" must mean what it says: allow every gateway that
        // applies to this language AND switch each one on globally, or the rows
        // stay ❌ and the button looks broken
        $gw_on = array_values(array_filter(gateway_all_keys(), fn($k) => gateway_applicable_for_lang($k, $gw_m[1])));
        gateway_set_for_lang($gw_m[1], $gw_on);
        foreach ($gw_on as $gw_k) {
            gateway_globally_set($gw_k, true);
        }
    } else {
        // off for this language only; the global switches stay as they are so
        // the other languages keep working
        gateway_set_for_lang($gw_m[1], []);
    }
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => $textbotlang['Admin']['GatewayLang']['saved'],
        'show_alert' => false,
        'cache_time' => 1,
    ]);
    Editmessagetext($from_id, $message_id, gateway_hub_caption($gw_m[1], $textbotlang), gateway_hub_payload($gw_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^gwglobal:([a-z]{2}):([a-z0-9]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if (!in_array($gw_m[2], gateway_all_keys(), true)) {
        return;
    }
    gateway_globally_set($gw_m[2], !gateway_globally_on($gw_m[2]));
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => $textbotlang['Admin']['GatewayLang']['saved'],
        'show_alert' => false,
        'cache_time' => 1,
    ]);
    Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_m[1], $gw_m[2], $textbotlang), gateway_settings_payload($gw_m[1], $gw_m[2], $textbotlang), 'HTML');
} elseif (preg_match('/^gwset:([a-z]{2}):([a-z0-9]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if (!in_array($gw_m[2], gateway_all_keys(), true)) {
        return;
    }
    gw_lang_settings_map(true);
    Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_m[1], $gw_m[2], $textbotlang), gateway_settings_payload($gw_m[1], $gw_m[2], $textbotlang), 'HTML');
} elseif (preg_match('/^tonmemo:([a-z]{2})$/', $datain, $tm_m) && $adminrulecheck['rule'] == "administrator") {
    Editmessagetext($from_id, $message_id, ton_memo_settings_caption($tm_m[1]), ton_memo_settings_payload($tm_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^tonmemolocked:([a-z]{2})$/', $datain, $tm_m) && $adminrulecheck['rule'] == "administrator") {
    // never becomes available - the reason is a property of a public chain,
    // not a setting, so this row explains rather than unlocks
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => topup_memo_locked_reason(),
        'show_alert' => true,
        'cache_time' => 1,
    ]);
} elseif (preg_match('/^tonmemoreset:([a-z]{2})$/', $datain, $tm_m) && $adminrulecheck['rule'] == "administrator") {
    topup_memo_reset($tm_m[1], 'ton');
    Editmessagetext($from_id, $message_id, ton_memo_settings_caption($tm_m[1]), ton_memo_settings_payload($tm_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^tonmemo(prefix|len):([a-z]{2})$/', $datain, $tm_m) && $adminrulecheck['rule'] == "administrator") {
    $tm_lim = topup_memo_limits();
    $tm_cfg = topup_memo_config($tm_m[2], 'ton');
    if ($tm_m[1] === 'prefix') {
        $tm_ask = "🔤 <b>پیشوند ممو را بفرستید</b>\n\n"
            . "فقط حروف انگلیسی و عدد، حداکثر {$tm_lim['prefixMax']} کاراکتر. مثال: <code>MirzaPro</code>\n\n"
            . "مقدار فعلی: " . ($tm_cfg['prefix'] === '' ? '<i>ندارد</i>' : "<code>{$tm_cfg['prefix']}</code>") . "\n"
            . "برای برداشتن پیشوند، عدد <b>0</b> را بفرستید.";
    } else {
        $tm_ask = "🎲 <b>طول بخش تصادفی را بفرستید</b>\n\n"
            . "عددی بین {$tm_lim['lenMin']} تا {$tm_lim['lenMax']}.\n\n"
            . "مقدار فعلی: <b>{$tm_cfg['len']}</b>";
    }
    $tm_prompt = sendmessage($from_id, $tm_ask, null, 'HTML');
    step("tonmemo:{$tm_m[1]}:{$tm_m[2]}:{$message_id}:" . (int) ($tm_prompt['result']['message_id'] ?? 0), $from_id);
} elseif (preg_match('/^tonmemo:(prefix|len):([a-z]{2}):([0-9]+):([0-9]+)$/', (string) $user['step'], $tm_m) && $datain == '') {
    $tm_lim = topup_memo_limits();
    $tm_val = trim((string) $text);
    deletemessage($from_id, $message_id);
    step("home", $from_id);
    if ($tm_m[1] === 'prefix') {
        // '0' is the agreed "clear this" shortcut across every gateway field,
        // and a bare digit makes a poor shop prefix anyway
        $tm_clean = $tm_val === '0' ? '' : topup_memo_clean_prefix($tm_val);
        if ($tm_val !== '0' && $tm_clean === '') {
            Editmessagetext($from_id, (int) $tm_m[4], "❌ پیشوند باید فقط از حروف انگلیسی و عدد باشد.", null, 'HTML');
            step("tonmemo:{$tm_m[1]}:{$tm_m[2]}:{$tm_m[3]}:{$tm_m[4]}", $from_id);
            return;
        }
        topup_memo_set($tm_m[2], 'ton', 'prefix', $tm_clean);
    } else {
        if (!ctype_digit($tm_val) || (int) $tm_val < $tm_lim['lenMin'] || (int) $tm_val > $tm_lim['lenMax']) {
            Editmessagetext($from_id, (int) $tm_m[4], "❌ عددی بین {$tm_lim['lenMin']} تا {$tm_lim['lenMax']} بفرستید.", null, 'HTML');
            step("tonmemo:{$tm_m[1]}:{$tm_m[2]}:{$tm_m[3]}:{$tm_m[4]}", $from_id);
            return;
        }
        topup_memo_set($tm_m[2], 'ton', 'len', (int) $tm_val);
    }
    deletemessage($from_id, (int) $tm_m[4]);
    Editmessagetext($from_id, (int) $tm_m[3], ton_memo_settings_caption($tm_m[2]), ton_memo_settings_payload($tm_m[2], $textbotlang), 'HTML');
} elseif (preg_match('/^gwname:([a-z]{2}):([a-z0-9_]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    // display-only label - explains the row instead of navigating anywhere
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => gateway_name_alert($gw_m[1], $gw_m[2], $textbotlang),
        'show_alert' => true,
        'cache_time' => 1,
    ]);
    return;
} elseif (preg_match('/^gwgroup:([a-z]{2}):([a-z0-9_]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if (!isset(gateway_groups()[$gw_m[2]])) {
        return;
    }
    Editmessagetext($from_id, $message_id, gateway_group_caption($gw_m[1], $gw_m[2], $textbotlang), gateway_group_payload($gw_m[1], $gw_m[2], $textbotlang), 'HTML');
} elseif (preg_match('/^gwgrouptoggle:([a-z]{2}):([a-z0-9_]+)$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    if (!isset(gateway_groups()[$gw_m[2]])) {
        return;
    }
    // all off -> switch the whole family on; anything else -> switch it all off.
    // Mirrors the single-gateway toggle above, including the rule that turning
    // one ON must also flip its global switch or the row lies about being live.
    $gw_turnOn = gateway_group_state($gw_m[2], $gw_m[1]) === 'none';
    $gw_members = gateway_group_members($gw_m[2], $gw_m[1]);
    $gw_keys = gateway_current_keys($gw_m[1]);
    if ($gw_turnOn) {
        foreach ($gw_members as $gw_key) {
            if (!in_array($gw_key, $gw_keys, true)) {
                $gw_keys[] = $gw_key;
            }
            gateway_globally_set($gw_key, true);
        }
    } else {
        $gw_keys = array_values(array_diff($gw_keys, $gw_members));
    }
    gateway_set_for_lang($gw_m[1], $gw_keys);
    Editmessagetext($from_id, $message_id, gateway_hub_caption($gw_m[1], $textbotlang), gateway_hub_payload($gw_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^cardrandtoggle:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    // global switch (not per-language) - see the comment on this button's
    // row in gateway_settings_payload()
    $crt_setting = select("setting", "cardRandomAmount, smsForwardEnabled", null, null, "select");
    if (($crt_setting['smsForwardEnabled'] ?? '0') === '1') {
        // defensive: the keyboard already hides this behind cardrandlocked:
        // while SMS Forward is on, but a stale/older render of this screen
        // could still send this callback - never silently toggle in that case
        telegram('answerCallbackQuery', [
            'callback_query_id' => $callback_query_id,
            'text' => '🔒 چون SMS Forward روشنه، این قابلیت قفله. اول SMS Forward رو خاموش کنید.',
            'show_alert' => true,
        ]);
        Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_m[1], 'card', $textbotlang), gateway_settings_payload($gw_m[1], 'card', $textbotlang), 'HTML');
        return;
    }
    $crt_on = (($crt_setting['cardRandomAmount'] ?? '0') === '1');
    update("setting", "cardRandomAmount", $crt_on ? '0' : '1', null, null);
    Editmessagetext($from_id, $message_id, gateway_settings_caption($gw_m[1], 'card', $textbotlang), gateway_settings_payload($gw_m[1], 'card', $textbotlang), 'HTML');
} elseif (preg_match('/^cardrandlocked:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => '🔒 چون SMS Forward روشنه، مبلغ رندوم قابل خاموش کردن نیست. اول SMS Forward رو خاموش کنید.',
        'show_alert' => true,
    ]);
} elseif (preg_match('/^smsfwdset:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    Editmessagetext($from_id, $message_id, "📲 <b>تنظیمات SMS Forward</b>", sms_forward_settings_payload($gw_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^smsfwdguide:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    list($sfw_info, $sfw_kb) = sms_forward_guide_payload($gw_m[1]);
    Editmessagetext($from_id, $message_id, $sfw_info, $sfw_kb, 'HTML');
} elseif (preg_match('/^smsfwdtoggle:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    // always lands back on this same settings screen now, whichever direction
    // it flipped - the setup guide has its own always-available "📖 راهنمای
    // نصب" button, so auto-jumping there on every re-enable (e.g. pausing and
    // resuming SMS Forward) was just an unwanted extra hop, not a help.
    sms_forward_toggle();
    Editmessagetext($from_id, $message_id, "📲 <b>تنظیمات SMS Forward</b>", sms_forward_settings_payload($gw_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^smsfwdshowurl:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    list($sfw_info, $sfw_kb) = sms_forward_show_url_payload($gw_m[1], false);
    Editmessagetext($from_id, $message_id, $sfw_info, $sfw_kb, 'HTML');
} elseif (preg_match('/^smsfwdregensecret:([a-z]{2})$/', $datain, $gw_m) && $adminrulecheck['rule'] == "administrator") {
    sms_forward_regenerate_secret();
    // stays on this same "نمایش آدرس Webhook" screen with the fresh URL
    // already substituted in, plus a success blockquote - not a transient
    // alert that then jumps back out to the settings screen.
    list($sfw_info, $sfw_kb) = sms_forward_show_url_payload($gw_m[1], true);
    Editmessagetext($from_id, $message_id, $sfw_info, $sfw_kb, 'HTML');
} elseif (preg_match('/^cardlegacy:([a-z]{2})$/', $datain, $cl_m) && $adminrulecheck['rule'] == "administrator") {
    Editmessagetext($from_id, $message_id, card_legacy_settings_caption($cl_m[1]), card_legacy_settings_payload($cl_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^cardlegacytoggle:([a-z]{2}):(\w+)$/', $datain, $cl_m) && $adminrulecheck['rule'] == "administrator") {
    $cl_fields = card_legacy_toggle_fields();
    if (!isset($cl_fields[$cl_m[2]])) {
        return;
    }
    $cl_def = $cl_fields[$cl_m[2]];
    $cl_on = pay_value($cl_m[2], $cl_m[1], $cl_def['off']) === $cl_def['on'];
    // defensive: the keyboard already routes this to cardlegacylocked: while
    // SMS Forward is on, but a stale render of the screen could still send it
    if (!$cl_on && $cl_m[2] === 'autoconfirmcart' && (select("setting", "smsForwardEnabled", null, null, "select")['smsForwardEnabled'] ?? '0') === '1') {
        telegram('answerCallbackQuery', [
            'callback_query_id' => $callback_query_id,
            'text' => '🔒 چون SMS Forward روشنه، تایید رسید بدون بررسی قابل روشن کردن نیست. اول SMS Forward رو خاموش کنید.',
            'show_alert' => true,
        ]);
        Editmessagetext($from_id, $message_id, card_legacy_settings_caption($cl_m[1]), card_legacy_settings_payload($cl_m[1], $textbotlang), 'HTML');
        return;
    }
    gw_pay_override_set($cl_m[2], $cl_m[1], $cl_on ? $cl_def['off'] : $cl_def['on']);
    Editmessagetext($from_id, $message_id, card_legacy_settings_caption($cl_m[1]), card_legacy_settings_payload($cl_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^cardlegacylocked:([a-z]{2})$/', $datain, $cl_m) && $adminrulecheck['rule'] == "administrator") {
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        // Telegram caps this at 200 characters - see the guard in telegram()
        'text' => '🔒 تا وقتی SMS Forward روشنه، این گزینه قابل روشن کردن نیست.

SMS Forward پرداخت رو با پیامک واقعی بانک تایید می‌کنه، ولی این یکی بدون بررسی و فقط با گذشت زمان.

اول SMS Forward رو خاموش کنید.',
        'show_alert' => true,
    ]);
} elseif (preg_match('/^cardlegacytimetoggle:([a-z]{2})$/', $datain, $cl_m) && $adminrulecheck['rule'] == "administrator") {
    if ((select("setting", "smsForwardEnabled", null, null, "select")['smsForwardEnabled'] ?? '0') === '1') {
        telegram('answerCallbackQuery', [
            'callback_query_id' => $callback_query_id,
            'text' => '🔒 چون SMS Forward روشنه، زمان تایید خودکار قابل روشن کردن نیست. اول SMS Forward رو خاموش کنید.',
            'show_alert' => true,
        ]);
        Editmessagetext($from_id, $message_id, card_legacy_settings_caption($cl_m[1]), card_legacy_settings_payload($cl_m[1], $textbotlang), 'HTML');
        return;
    }
    // 0 = off. Turning it on starts at 20 minutes; "✏️ تغییر زمان" then edits
    // that number through the same prompt as before (which only accepts 1+, so
    // it can never write the off-sentinel back).
    $cl_timeOn = intval(pay_value('timeauto_not_verify', $cl_m[1], '0')) > 0;
    gw_pay_override_set('timeauto_not_verify', $cl_m[1], $cl_timeOn ? '0' : '20');
    Editmessagetext($from_id, $message_id, card_legacy_settings_caption($cl_m[1]), card_legacy_settings_payload($cl_m[1], $textbotlang), 'HTML');
} elseif (preg_match('/^cardlegacyclose:([a-z]{2})$/', $datain, $cl_m) && $adminrulecheck['rule'] == "administrator") {
    step('home', $from_id);
    deletemessage($from_id, $message_id);
    sendmessage($from_id, $textbotlang['bottext']['msg_closed'], null, 'HTML');
} elseif (preg_match('/^cardlegacytime:([a-z]{2})$/', $datain, $cl_m) && $adminrulecheck['rule'] == "administrator") {
    $cl_prompt = sendmessage($from_id, sprintf($textbotlang['Admin']['Payment']['askAutoConfirmMinutes'], pay_value('timeauto_not_verify', $cl_m[1], '0')), null, 'HTML');
    $cl_promptId = (int) ($cl_prompt['result']['message_id'] ?? 0);
    step("cardlegacytime:{$cl_m[1]}:{$message_id}:{$cl_promptId}", $from_id);
} elseif (preg_match('/^cardlegacytime:([a-z]{2}):([0-9]+):([0-9]+)$/', (string) $user['step'], $cl_m) && $datain == '') {
    if (!ctype_digit(trim((string) $text)) || (int) trim((string) $text) < 1) {
