            'text' => $textbotlang['Admin']['card']['noUsersEnabled'],
            'show_alert' => true,
        ]);
    } else {
        $cl_filename = 'cartlist.txt';
        if (file_exists($cl_filename)) {
            unlink($cl_filename);
        }
        foreach ($cl_listusers as $cl_u) {
            file_put_contents($cl_filename, $cl_u['id'] . "\n", FILE_APPEND);
