} elseif (preg_match('/^langscope_casc_apply:(\d+):([01]{5})$/', $datain, $lc_m) && $adminrulecheck['rule'] == "administrator") {
    $lc_id = $lc_m[1];
    $lc_bitmask = $lc_m[2];
    if (strpos($lc_bitmask, '1') === false) {
        telegram('answerCallbackQuery', [
            'callback_query_id' => $callback_query_id,
            'text' => $textbotlang['Admin']['LangScope']['cascadeNeedOne'],
            'show_alert' => true,
            'cache_time' => 1,
        ]);
        return;
    }
    $lc_cat = select("category", "*", "id", $lc_id, "select");
    if (!$lc_cat) {
        telegram('answerCallbackQuery', [
            'callback_query_id' => $callback_query_id,
            'text' => $textbotlang['Admin']['LangScope']['emptyList'],
            'show_alert' => true,
            'cache_time' => 1,
        ]);
        return;
    }
    $lc_picked = langscope_casc_bitmask_to_langs($lc_bitmask);
    $lc_langValue = (count($lc_picked) === 5) ? 'all' : implode(',', $lc_picked);
    update("category", "lang", $lc_langValue, "id", $lc_id);
    update("product", "lang", $lc_langValue, "category", $lc_cat['remark']);
    $lc_prodCount = select("product", "*", "category", $lc_cat['remark'], "count");
    $lc_locs = $pdo->prepare("SELECT DISTINCT Location FROM product WHERE category = ? AND Location != '/all'");
    $lc_locs->execute([$lc_cat['remark']]);
    $lc_panelsTouched = [];
    $lc_panelsShared = [];
    while ($lc_loc = $lc_locs->fetchColumn()) {
        $lc_panel = select("marzban_panel", "*", "name_panel", $lc_loc, "select");
        if ($lc_panel) {
            update("marzban_panel", "lang", $lc_langValue, "name_panel", $lc_loc);
            $lc_panelsTouched[] = $lc_loc;
            $lc_shareCheck = $pdo->prepare("SELECT DISTINCT category FROM product WHERE Location = ? AND category != ?");
            $lc_shareCheck->execute([$lc_loc, $lc_cat['remark']]);
            $lc_otherCats = $lc_shareCheck->fetchAll(PDO::FETCH_COLUMN);
            if (!empty($lc_otherCats)) {
                $lc_panelsShared[$lc_loc] = $lc_otherCats;
            }
        }
    }
    $lc_langNames = array_map(function ($c) use ($textbotlang) {
        return $textbotlang['bottext']['langs'][$c];
    }, $lc_picked);
    $lc_msg = sprintf($textbotlang['Admin']['LangScope']['cascadeDone'], $lc_cat['remark'], $lc_prodCount, implode('، ', $lc_langNames));
