    help_set_lang_field($help_parts[0], $help_parts[1], ['category' => $text]);
    list($help_info, $help_kb) = help_item_menu_payload($help_parts[0], $help_parts[1], $textbotlang);
    sendmessage($from_id, $textbotlang['Admin']['Help']['categorySaved'] . "\n\n" . $help_info, $help_kb, 'HTML');
    step('home', $from_id);
} elseif (preg_match('/^help_edit:(\d+):(fa|en|ru|zh|tk)$/', $datain, $help_m) && $adminrulecheck['rule'] == "administrator") {
    update("user", "Processing_value", $help_m[1] . ':' . $help_m[2], "id", $from_id);
    sendmessage($from_id, $textbotlang['Admin']['Help']['askOnlyContent'], $backadmin, 'HTML');
    step('help_edit_content', $from_id);
} elseif ($user['step'] == "help_edit_content") {
    $help_parts = explode(':', (string) $user['Processing_value']);
    if (count($help_parts) < 2) {
        step('home', $from_id);
        return;
    }
    $help_id = $help_parts[0];
    $help_lang = $help_parts[1];
    $help_media = '';
    $help_media_type = '';
    $help_desc = '';
    $help_entities = null;
    if ($photo) {
        if (isset($photoid))
            $help_media = $photoid;
        $help_media_type = 'photo';
        $help_desc = $caption;
        $help_entities = $update['message']['caption_entities'] ?? null;
    } elseif ($video) {
        if (isset($videoid))
            $help_media = $videoid;
        $help_media_type = 'video';
        $help_desc = $caption;
        $help_entities = $update['message']['caption_entities'] ?? null;
    } elseif ($document) {
        if (isset($fileid))
            $help_media = $fileid;
        $help_media_type = 'document';
        $help_desc = $caption;
        $help_entities = $update['message']['caption_entities'] ?? null;
    } elseif ($text) {
        $help_desc = $text;
        $help_entities = $update['message']['entities'] ?? null;
    } else {
        sendmessage($from_id, $textbotlang['Admin']['Help']['invalidContent'], $backadmin, 'HTML');
        return;
    }
    // description/media/entities are written together on purpose: entity
    // offsets only line up with the exact text they were captured from
    help_set_lang_field($help_id, $help_lang, [
        'description' => $help_desc,
        'media' => $help_media,
        'media_type' => $help_media_type,
        'entities' => $help_entities,
    ]);
    list($help_info, $help_kb) = help_item_menu_payload($help_id, $help_lang, $textbotlang);
    sendmessage($from_id, $textbotlang['Admin']['Help']['contentSaved'] . "\n\n" . $help_info, $help_kb, 'HTML');
    step('home', $from_id);
} elseif ($user['step'] == "help_emo_input" && $datain == '') {
    $help_parts = explode(':', (string) $user['Processing_value']);
    if (count($help_parts) < 3) {
        step('home', $from_id);
        return;
    }
    $help_kind = $help_parts[0];
    $help_lang = $help_parts[1];
    $help_idx = (int) $help_parts[2];
    $help_items = help_layout_items($help_lang, $help_kind);
    $help_section = help_layout_section($help_lang, $help_kind);
    $help_ordered = help_layout_apply_order(array_keys($help_items), $help_section['order']);
    $help_key = $help_ordered[$help_idx] ?? null;
    if ($help_key === null) {
        step('home', $from_id);
        return;
    }
    if ($text == '0') {
        unset($help_section['emoji'][$help_key], $help_section['emojiIcon'][$help_key]);
    } else {
        $help_icon_id = '';
        if (!empty($update['message']['entities']) && is_array($update['message']['entities'])) {
            foreach ($update['message']['entities'] as $help_ent) {
                if (($help_ent['type'] ?? '') === 'custom_emoji' && !empty($help_ent['custom_emoji_id'])) {
                    $help_icon_id = $help_ent['custom_emoji_id'];
                    break;
                }
            }
        }
        if ($help_icon_id !== '') {
            $help_section['emojiIcon'][$help_key] = $help_icon_id;
            unset($help_section['emoji'][$help_key]);
        } else {
            preg_match('/^\X/u', trim((string) $text), $help_em);
            $help_emoji = $help_em[0] ?? '';
            if ($help_emoji === '' || preg_match('/^[0-9a-zA-Z]$/', $help_emoji)) {
                sendmessage($from_id, "⚠️ لطفاً یه ایموجی (معمولی یا پریمیوم) بفرست 😅", $backadmin, 'HTML');
                return;
            }
            $help_section['emoji'][$help_key] = $help_emoji;
            unset($help_section['emojiIcon'][$help_key]);
        }
    }
    help_layout_set_section($help_lang, $help_kind, $help_section);
    step('home', $from_id);
    $help_kb = help_emoji_editor_payload($help_lang, $help_kind, $textbotlang);
    sendmessage($from_id, $textbotlang['Admin']['Help']['emojiSaved'] . "\n\n" . $textbotlang['Admin']['Help']['emojiCaption'], $help_kb, 'HTML');
} elseif ($user['step'] == "help_ren_input" && $datain == '') {
    $help_parts = explode(':', (string) $user['Processing_value']);
    if (count($help_parts) < 3) {
        step('home', $from_id);
        return;
    }
    $help_kind = $help_parts[0];
    $help_lang = $help_parts[1];
    $help_idx = (int) $help_parts[2];
    $help_items = help_layout_items($help_lang, $help_kind);
    $help_section = help_layout_section($help_lang, $help_kind);
    $help_ordered = help_layout_apply_order(array_keys($help_items), $help_section['order']);
    $help_key = $help_ordered[$help_idx] ?? null;
    if ($help_key === null) {
        step('home', $from_id);
        return;
    }
    if ($text == '0') {
        unset($help_section['rename'][$help_key]);
    } else {
        $help_newname = trim((string) $text);
        if ($help_newname === '') {
            sendmessage($from_id, $textbotlang['Admin']['Help']['invalidContent'], $backadmin, 'HTML');
            return;
        }
        if (mb_strlen($help_newname) > 150) {
            sendmessage($from_id, $textbotlang['Admin']['Help']['nameTooLong'], $backadmin, 'HTML');
            return;
        }
        $help_section['rename'][$help_key] = $help_newname;
    }
    help_layout_set_section($help_lang, $help_kind, $help_section);
    step('home', $from_id);
    $help_kb = help_rename_editor_payload($help_lang, $help_kind, $textbotlang);
    sendmessage($from_id, $textbotlang['Admin']['BtnStyle']['renameSaved'] . "\n\n" . $textbotlang['Admin']['BtnStyle']['renameCaption'], $help_kb, 'HTML');
} elseif (preg_match('/^help_reset:(\d+):(en|ru|zh|tk)$/', $datain, $help_m) && $adminrulecheck['rule'] == "administrator") {
    $help_id = $help_m[1];
    $help_lang = $help_m[2];
    $help_row = select("help", "*", "id", $help_id, "select");
    if ($help_row !== false) {
        $help_tr = json_decode((string) ($help_row['translations'] ?? ''), true);
        if (is_array($help_tr) && isset($help_tr[$help_lang])) {
            unset($help_tr[$help_lang]);
            update("help", "translations", json_encode($help_tr, JSON_UNESCAPED_UNICODE), "id", $help_id);
        }
    }
    list($help_info, $help_kb) = help_item_menu_payload($help_id, $help_lang, $textbotlang);
    Editmessagetext($from_id, $message_id, $textbotlang['Admin']['Help']['resetDone'] . "\n\n" . $help_info, $help_kb, 'HTML');
} elseif (preg_match('/^help_delete:(\d+):(fa|en|ru|zh|tk)$/', $datain, $help_m) && $adminrulecheck['rule'] == "administrator") {
    $help_id = intval($help_m[1]);
    $help_lang = $help_m[2];
    $stmt = $pdo->prepare("DELETE FROM help WHERE id = :id");
    $stmt->bindValue(':id', $help_id, PDO::PARAM_INT);
    $stmt->execute();
    clearSelectCache('help');
    list($help_caption, $help_kb) = help_home_payload($help_lang, $textbotlang);
    Editmessagetext($from_id, $message_id, $textbotlang['Admin']['Help']['removeHelp'] . "\n\n" . $help_caption, $help_kb, 'HTML');
} elseif ($datain == "help_close") {
    deletemessage($from_id, $message_id);
} elseif ($datain == "bt_close") {
    deletemessage($from_id, $message_id);
    sendmessage($from_id, $textbotlang['bottext']['msg_closed'], null, 'HTML');
} elseif (preg_match('/^bt_lang:([a-z]{2})(?::(\w+))?$/', $datain, $dataget)) {
    $lang = $dataget[1];
    $bt_lang_group = $dataget[2] ?? null;
    list($bt_home, $bt_kb) = keyboard_list_text($lang, $bt_lang_group);
    Editmessagetext($from_id, $message_id, $bt_home, $bt_kb);
} elseif (preg_match('/^bt_resetall\|(.+)$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    $bt_lang = $dataget[1];
    if (!in_array($bt_lang, ['fa', 'en', 'ru', 'zh', 'tk'], true)) {
        $bt_lang = 'fa';
    }
    // no longer wipes on the spot - opens the picker so the admin sees exactly
    // what is about to go and can narrow it down. Everything starts selected,
    // so the old "tap once, reset everything" path is still just two taps.
    list($bt_rp_text, $bt_rp_kb) = bt_reset_picker_payload($bt_lang, 255, $textbotlang);
    Editmessagetext($from_id, $message_id, $bt_rp_text, $bt_rp_kb, 'HTML');
} elseif (preg_match('/^bt_rsttog\|([a-z]{2})\|(\d{1,3})\|(\d{1,3})$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    $bt_lang = in_array($dataget[1], ['fa', 'en', 'ru', 'zh', 'tk'], true) ? $dataget[1] : 'fa';
    $bt_mask = ((int) $dataget[2]) & 255;
    $bt_bit = ((int) $dataget[3]) & 255;
    $bt_mask = ($bt_mask & $bt_bit) ? ($bt_mask & ~$bt_bit) : ($bt_mask | $bt_bit);
    list($bt_rp_text, $bt_rp_kb) = bt_reset_picker_payload($bt_lang, $bt_mask, $textbotlang);
    Editmessagetext($from_id, $message_id, $bt_rp_text, $bt_rp_kb, 'HTML');
} elseif (preg_match('/^bt_rstsel\|([a-z]{2})\|(all|none)$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    $bt_lang = in_array($dataget[1], ['fa', 'en', 'ru', 'zh', 'tk'], true) ? $dataget[1] : 'fa';
    $bt_mask = ($dataget[2] === 'all') ? 255 : 0;
    list($bt_rp_text, $bt_rp_kb) = bt_reset_picker_payload($bt_lang, $bt_mask, $textbotlang);
    Editmessagetext($from_id, $message_id, $bt_rp_text, $bt_rp_kb, 'HTML');
} elseif ($datain == "bt_rstsep" && $adminrulecheck['rule'] == "administrator") {
    telegram('answerCallbackQuery', [
        'callback_query_id' => $callback_query_id,
        'text' => 'این‌ها تنظیمات ظاهری دکمه‌های ثابت پایین صفحه‌ی کاربرن - نه متن پیام‌ها.',
        'show_alert' => true,
    ]);
    return;
} elseif (preg_match('/^bt_rstgo\|([a-z]{2})\|(\d{1,3})$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    $bt_lang = in_array($dataget[1], ['fa', 'en', 'ru', 'zh', 'tk'], true) ? $dataget[1] : 'fa';
    $bt_mask = ((int) $dataget[2]) & 255;
    if ($bt_mask === 0) {
        telegram('answerCallbackQuery', [
            'callback_query_id' => $callback_query_id,
            'text' => 'هیچ بخشی انتخاب نشده - اول تیک بخش‌هایی که می‌خوای ریست بشن رو بزن.',
            'show_alert' => true,
        ]);
        return;
    }
    $bt_rp_done = bt_reset_apply_mask($bt_lang, $bt_mask, $textbotlang);
    $textbotlang = ui_texts();
    list($bt_home, $bt_kb) = keyboard_list_text($bt_lang);
    $bt_rp_msg = empty($bt_rp_done)
        ? "ℹ️ چیزی برای ریست نبود - بخش‌های انتخابی از قبل روی پیش‌فرض بودن."
        : ("✅ <b>ریست شد:</b>\n" . implode("\n", $bt_rp_done));
    Editmessagetext($from_id, $message_id, $bt_rp_msg . "\n\n" . $bt_home, $bt_kb, 'HTML');
} elseif (preg_match('/^bt_group_resetall\|([^|]+)\|(.+)$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    $bt_lang = $dataget[1];
    $bt_group = $dataget[2];
    if (!in_array($bt_lang, ['fa', 'en', 'ru', 'zh', 'tk'], true)) {
        $bt_lang = 'fa';
    }
    $bt_group_keys = array_column(array_filter($textbotlang['bottext']['items'], function ($it) use ($bt_group) {
        return ($it['group'] ?? '') === $bt_group;
    }), 'key');
    bottext_reset_keys($bt_group_keys, $bt_lang);
    $textbotlang = ui_texts();
    list($bt_group_text, $bt_group_kb) = keyboard_list_text($bt_lang, $bt_group);
    Editmessagetext($from_id, $message_id, $textbotlang['bottext']['resetAllDone'] . "\n\n" . $bt_group_text, $bt_group_kb, 'HTML');
} elseif (preg_match('/^bt_group\|([^|]+)\|(.+)$/', $datain, $dataget) && $adminrulecheck['rule'] == "administrator") {
    $bt_lang = $dataget[1];
    $bt_group = $dataget[2];
    if (!in_array($bt_lang, ['fa', 'en', 'ru', 'zh', 'tk'], true)) {
        $bt_lang = 'fa';
    }
    list($bt_group_text, $bt_group_kb) = keyboard_list_text($bt_lang, $bt_group);
    Editmessagetext($from_id, $message_id, $bt_group_text, $bt_group_kb, 'HTML');
} elseif (preg_match('/^bt_edit\|([^|]+)\|(.+)$/', $datain, $dataget)) {
    $bt_lang = $dataget[1];
    $bt_key = $dataget[2];
    if (!in_array($bt_lang, ['fa', 'en', 'ru', 'zh', 'tk'], true)) {
        $bt_lang = 'fa';
    }
    list($btm_text, $btm_kb) = bottext_item_menu_payload($bt_key, $bt_lang, $textbotlang);
    Editmessagetext($from_id, $message_id, $btm_text, $btm_kb, 'HTML');
} elseif ($user['step'] == "get_new_text") {
    $userdata = json_decode((string) ($user['Processing_value'] ?? ''), true);
    if (!is_array($userdata)) {
        $userdata = [];
    }
    $bt_lang = $userdata['bt_lang'] ?? 'fa';
    $bt_key = $userdata['bt_key'] ?? '';
    $bt_msgid = intval($userdata['bt_msgid'] ?? 0);
    if (!in_array($bt_lang, ['fa', 'en', 'ru', 'zh', 'tk'], true)) {
        $bt_lang = 'fa';
    }
    $bt_valid = false;
    foreach (($textbotlang['bottext']['items'] ?? []) as $bt_it) {
        if (($bt_it['key'] ?? '') === $bt_key) {
            $bt_valid = true;
            break;
        }
    }
    if ($bt_key === 'users.unknownMsg') {
        $bt_valid = true;
    }
    if (in_array($bt_key, ['textbot.afterText', 'users.status.getConfigHint'], true)) {
        $bt_valid = true;
    }
    if (!$bt_valid || $bt_key === '') {
        step('home', $from_id);
        sendmessage($from_id, $textbotlang['bottext']['msg_session'], $keyboardadmin, 'HTML');
        return;
    }
    $bt_new = (string) ($update['message']['text'] ?? $text);
    // bake premium (custom) emoji into <tg-emoji> HTML tags so the bot re-sends them rendered
    if (!empty($update['message']['entities']) && is_array($update['message']['entities'])) {
        $bt_ents = [];
        foreach ($update['message']['entities'] as $bt_ent) {
            if (($bt_ent['type'] ?? '') === 'custom_emoji' && !empty($bt_ent['custom_emoji_id']) && isset($bt_ent['offset'], $bt_ent['length'])) {
                $bt_ents[] = $bt_ent;
            }
        }
        if (!empty($bt_ents)) {
            usort($bt_ents, function ($a, $b) {
                return intval($b['offset']) <=> intval($a['offset']);
            });
            $bt_utf16 = mb_convert_encoding($bt_new, 'UTF-16LE', 'UTF-8');
            foreach ($bt_ents as $bt_ent) {
                $bt_bo = intval($bt_ent['offset']) * 2;
                $bt_bl = intval($bt_ent['length']) * 2;
                $bt_char = substr($bt_utf16, $bt_bo, $bt_bl);
                if ($bt_char === '' || $bt_char === false) {
                    continue;
                }
                $bt_tag = '<tg-emoji emoji-id="' . $bt_ent['custom_emoji_id'] . '">' . mb_convert_encoding($bt_char, 'UTF-8', 'UTF-16LE') . '</tg-emoji>';
                $bt_utf16 = substr($bt_utf16, 0, $bt_bo) . mb_convert_encoding($bt_tag, 'UTF-16LE', 'UTF-8') . substr($bt_utf16, $bt_bo + $bt_bl);
            }
            $bt_new = mb_convert_encoding($bt_utf16, 'UTF-8', 'UTF-16LE');
        }
    }
    $bt_new = trim($bt_new);
    if ($bt_new === '') {
        sendmessage($from_id, $textbotlang['bottext']['msg_empty'], $backadmin, 'HTML');
        return;
    }
    $bt_map = (isset($setting['text_edit']) && $setting['text_edit']) ? json_decode($setting['text_edit'], true) : [];
    if (!is_array($bt_map)) {
        $bt_map = [];
    }
    $bt_reset = $bt_new === '0';
    if ($bt_reset) {
        if (isset($bt_map[$bt_lang]) && is_array($bt_map[$bt_lang])) {
            bottext_dotted_unset($bt_map[$bt_lang], $bt_key);
            if (empty($bt_map[$bt_lang])) {
                unset($bt_map[$bt_lang]);
            }
        }
    } else {
        if (!isset($bt_map[$bt_lang]) || !is_array($bt_map[$bt_lang])) {
            $bt_map[$bt_lang] = [];
        }
        bottext_dotted_set($bt_map[$bt_lang], $bt_key, $bt_new);
    }
    update("setting", "text_edit", empty($bt_map) ? null : json_encode($bt_map, JSON_UNESCAPED_UNICODE), null, null);
    step('home', $from_id);
    $textbotlang = ui_texts();
    list($bt_home, $bt_kb) = keyboard_list_text($bt_lang);
    $bt_done_msg = ($bt_reset ? $textbotlang['bottext']['msg_reset_done'] : $textbotlang['bottext']['msg_saved']) . "\n\n" . $bt_home;
    if ($message_id) {
        deletemessage($from_id, $message_id);
    }
    if ($bt_msgid > 0) {
        Editmessagetext($from_id, $bt_msgid, $bt_done_msg, $bt_kb, 'HTML');
    } else {
        sendmessage($from_id, $bt_done_msg, $bt_kb, 'HTML');
    }
}
